// Data grammar-n4 — dihasilkan otomatis (lihat scripts/fetch-data.mjs).
export default [{"pattern":"A とか B とか","meaning":"Used to express multiple examples or possibilities; 'such as', 'like', 'for example'.","formation":"Noun + とか + Noun + とか","examples":[{"jp":"週末は映画とか買い物とか楽しいことをしたいです。","en":"I want to do fun things like watching movies and shopping on the weekend.","romaji":"Shuumatsu wa eiga toka kaimono toka tanoshii koto o shitai desu."},{"jp":"彼女は英語とかフランス語とかいろいろな言葉を話せます。","en":"She can speak various languages, like English and French.","romaji":"Kanojo wa eigo toka furansugo toka iroirona kotoba o hanasemasu."},{"jp":"この店は寿司とか刺身とか日本料理を提供しています。","en":"This restaurant offers Japanese dishes such as sushi and sashimi.","romaji":"Kono mise wa sushi toka sashimi toka nihon ryouri o teikyou shiteimasu."},{"jp":"$1BOXとか$5BOXとか、異なる価格のランチBOXがあります。","en":"There are lunch boxes with different prices, like $1 boxes and $5 boxes.","romaji":"Ichi-doru BOX toka go-doru BOX toka, kotonaru kakaku no ranchi BOX ga arimasu."}],"example":"週末は映画とか買い物とか楽しいことをしたいです。","exampleMeaning":"I want to do fun things like watching movies and shopping on the weekend."},{"pattern":"A は B ほど～ありません","meaning":"Express that A is not as much as B; 'not as... as', 'not... to the extent of'.","formation":"A は B ほど Verb/adjective ありません","examples":[{"jp":"今日は昨日ほど寒くありません。","en":"Today is not as cold as yesterday.","romaji":"Kyou wa kinou hodo samuku arimasen."},{"jp":"彼は私ほど上手に英語を話せません。","en":"He cannot speak English as well as I can.","romaji":"Kare wa watashi hodo jouzu ni eigo o hanasemasen."},{"jp":"このレストランはあのレストランほど高くありません。","en":"This restaurant is not as expensive as that restaurant.","romaji":"Kono resutoran wa ano resutoran hodo takaku arimasen."},{"jp":"彼女は彼ほど忙しくありません。","en":"She is not as busy as him.","romaji":"Kanojo wa kare hodo isogashiku arimasen."}],"example":"今日は昨日ほど寒くありません。","exampleMeaning":"Today is not as cold as yesterday."},{"pattern":"A は B ほど～ない","meaning":"Expressing that A is not as ~ as B; 'not as...as'","formation":"A は B ほど + い-Adjective stem (without い) + くない, な-Adjective + じゃない, Verb-negative potential form","examples":[{"jp":"山田さんは鈴木さんほど背が高くない。","en":"Yamada is not as tall as Suzuki.","romaji":"Yamada-san wa Suzuki-san hodo se ga takakunai."},{"jp":"このリンゴはあのリンゴほど甘くない。","en":"This apple is not as sweet as that apple.","romaji":"Kono ringo wa ano ringo hodo amakunai."},{"jp":"彼は私ほど勉強ができない。","en":"He can't study as well as I can.","romaji":"Kare wa watashi hodo benkyou ga dekinai."},{"jp":"このレストランはあのレストランほど静かじゃない。","en":"This restaurant is not as quiet as that restaurant.","romaji":"Kono resutoran wa ano resutoran hodo shizuka janai."}],"example":"山田さんは鈴木さんほど背が高くない。","exampleMeaning":"Yamada is not as tall as Suzuki."},{"pattern":"A より B のほうが〜 (A yori B no hou ga 〜)","meaning":"Comparing two things; 'B is more ~ than A'.","formation":"A + より + B + のほうが + Adjective/Verb","examples":[{"jp":"田中さんより鈴木さんのほうが背が高いです。","en":"Suzuki is taller than Tanaka.","romaji":"Tanaka-san yori Suzuki-san no hou ga se ga takai desu."},{"jp":"リンゴよりバナナのほうが甘いです。","en":"Bananas are sweeter than apples.","romaji":"Ringo yori banana no hou ga amai desu."},{"jp":"冬より夏のほうが暑いです。","en":"Summer is hotter than winter.","romaji":"Fuyu yori natsu no hou ga atsui desu."},{"jp":"東京より京都のほうが歴史があると思います。","en":"I think Kyoto has more history than Tokyo.","romaji":"Toukyou yori Kyouto no hou ga rekishi ga aru to omoimasu."}],"example":"田中さんより鈴木さんのほうが背が高いです。","exampleMeaning":"Suzuki is taller than Tanaka."},{"pattern":"い-Adjective く する/なる (i-Adjective kusuru/naru)","meaning":"Express a change happening or making something change.","formation":"い-Adjective (remove い) + く + する/なる","examples":[{"jp":"部屋を明るくします。","en":"I will make the room brighter.","romaji":"Heya o akaruku shimasu."},{"jp":"彼の顔は赤くなりました。","en":"His face turned red.","romaji":"Kare no kao wa akaku narimashita."},{"jp":"この料理を辛くしてください。","en":"Please make this dish spicy.","romaji":"Kono ryouri o karaku shite kudasai."},{"jp":"雨が降ると、道が滑りやすくなります。","en":"When it rains, the road becomes slippery.","romaji":"Ame ga furu to, michi ga suberiyasuku narimasu."}],"example":"部屋を明るくします。","exampleMeaning":"I will make the room brighter."},{"pattern":"な-adjective に する/なる","meaning":"Used to indicate change or decision; 'to become' or 'to make' with na-adjectives.","formation":"な-Adjective + に + する/なる","examples":[{"jp":"部屋をきれいにする。","en":"To make the room clean.","romaji":"Heya o kirei ni suru."},{"jp":"彼は元気になりました。","en":"He became energetic.","romaji":"Kare wa genki ni narimashita."},{"jp":"毎日静かにすることが大切です。","en":"It is important to make it quiet every day.","romaji":"Mainichi shizuka ni suru koto ga taisetsu desu."},{"jp":"日本語の勉強が楽しくなるように努力します。","en":"I will try to make studying Japanese become enjoyable.","romaji":"Nihongo no benkyou ga tanoshiku naru you ni doryoku shimasu."}],"example":"部屋をきれいにする。","exampleMeaning":"To make the room clean."},{"pattern":"Noun しか～ない","meaning":"Expresses 'only', 'nothing but', or 'no other'.","formation":"Noun + しか + Negative Verb","examples":[{"jp":"私はリンゴしか食べない。","en":"I eat only apples.","romaji":"Watashi wa ringo shika tabenai."},{"jp":"電車で行くしかないです。","en":"There is no other way but to go by train.","romaji":"Densha de iku shika nai desu."},{"jp":"彼は一冊の本しか持っていない。","en":"He has only one book.","romaji":"Kare wa isatsu no hon shika motte inai."},{"jp":"この店にはビールしかない。","en":"There is nothing but beer in this store.","romaji":"Kono mise ni wa biiru shika nai."}],"example":"私はリンゴしか食べない。","exampleMeaning":"I eat only apples."},{"pattern":"Noun に する","meaning":"Used to indicate a choice or decision, 'to decide on' or 'to choose'.","formation":"Noun + に + する","examples":[{"jp":"メニューからピザにしました。","en":"I decided on pizza from the menu.","romaji":"Menyu kara piza ni shimashita."},{"jp":"誕生日プレゼントに時計にするつもりです。","en":"I plan to choose a watch as a birthday present.","romaji":"Tanjoubi purezento ni tokei ni suru tsumori desu."},{"jp":"今日の午後は買い物にすることにしました。","en":"I decided to go shopping this afternoon.","romaji":"Kyou no gogo wa kaimono ni suru koto ni shimashita."},{"jp":"海外旅行の目的地として、日本にする。","en":"I will choose Japan as the destination for my overseas trip.","romaji":"Kaigai ryokou no mokutekichi toshite, Nihon ni suru."}],"example":"メニューからピザにしました。","exampleMeaning":"I decided on pizza from the menu."},{"pattern":"Noun に なる","meaning":"To become; to change into; to turn into.","formation":"Noun + に + なる","examples":[{"jp":"彼は医者になりました。","en":"He became a doctor.","romaji":"Kare wa isha ni narimashita."},{"jp":"子供の頃、私は先生になりたかったです。","en":"When I was a child, I wanted to become a teacher.","romaji":"Kodomo no koro, watashi wa sensei ni naritakatta desu."},{"jp":"彼女は緊張して顔が赤くなりました。","en":"She got nervous, and her face turned red.","romaji":"Kanojo wa kinchou shite kao ga akaku narimashita."},{"jp":"春になると桜が咲きます。","en":"When it becomes spring, cherry blossoms bloom.","romaji":"Haru ni naru to sakura ga sakimasu."}],"example":"彼は医者になりました。","exampleMeaning":"He became a doctor."},{"pattern":"のために","meaning":"Used to express purpose or reason; 'for', 'for the sake of', 'in order to'.","formation":"Noun + のために","examples":[{"jp":"勉強のために、図書館で静かな場所を探しています。","en":"In order to study, I am looking for a quiet place in the library.","romaji":"Benkyou no tame ni, toshokan de shizukana basho o sagashiteimasu."},{"jp":"彼は家族のために、一生懸命働いています。","en":"He works hard for the sake of his family.","romaji":"Kare wa kazoku no tame ni, isshoukenmei hataraiteimasu."},{"jp":"健康のために、毎日運動をしています。","en":"I exercise every day for the sake of my health.","romaji":"Kenkou no tame ni, mainichi undou o shiteimasu."},{"jp":"世界平和のために、みんなで協力しましょう。","en":"Let's all cooperate for the sake of world peace.","romaji":"Sekai heiwa no tame ni, minna de kyouryoku shimashou."}],"example":"勉強のために、図書館で静かな場所を探しています。","exampleMeaning":"In order to study, I am looking for a quiet place in the library."},{"pattern":"Noun の 間に (〜no aida ni)","meaning":"Expresses 'while' or 'during' a specific period or time.","formation":"Noun + の間に","examples":[{"jp":"昼休みの間に銀行に行きます。","en":"I will go to the bank during lunch break.","romaji":"Hiruyasumi no aida ni ginkou ni ikimasu."},{"jp":"夏休みの間に海外旅行に行く予定です。","en":"I plan to go on an overseas trip during the summer vacation.","romaji":"Natsuyasumi no aida ni kaigai ryokou ni iku yotei desu."},{"jp":"子供たちが学校の間に買い物に行きました。","en":"I went shopping while the kids were at school.","romaji":"Kodomo-tachi ga gakkou no aida ni kaimono ni ikimashita."},{"jp":"母の日にお母さんにプレゼントを送りました。","en":"I sent a gift to my mother on Mother’s Day.","romaji":"Haha no hi ni okaasan ni purezento o okurimashita."}],"example":"昼休みの間に銀行に行きます。","exampleMeaning":"I will go to the bank during lunch break."},{"pattern":"Noun ばかり (〜bakari)","meaning":"Expresses 'only', 'nothing but', 'always', or 'just'.","formation":"Noun + ばかり, Verb-casual + ばかり, い-Adjective + ばかり, な-Adjective + だ ばかり","examples":[{"jp":"彼はお金の話ばかりする。","en":"He talks about nothing but money.","romaji":"Kare wa okane no hanashi bakari suru."},{"jp":"彼女は勉強ばかりしている。","en":"She is always studying.","romaji":"Kanojo wa benkyou bakari shiteiru."},{"jp":"デパートには高い商品ばかりだ。","en":"There are only expensive items in the department store.","romaji":"Depaato ni wa takai shouhin bakari da."},{"jp":"この部屋は狭いばかりだ。","en":"This room is nothing but small.","romaji":"Kono heya wa semai bakari da."}],"example":"彼はお金の話ばかりする。","exampleMeaning":"He talks about nothing but money."},{"pattern":"Noun を あげる","meaning":"To give something to someone; 'give', 'offer', 'present'.","formation":"Noun + を + あげる","examples":[{"jp":"プレゼントをあげる。","en":"I give a present.","romaji":"Purezento wo ageru."},{"jp":"友達に花をあげた。","en":"I gave flowers to my friend.","romaji":"Tomodachi ni hana wo ageta."},{"jp":"父に時計をあげます。","en":"I will give a watch to my father.","romaji":"Chichi ni tokei wo agemasu."},{"jp":"彼女に手紙をあげたい。","en":"I want to give her a letter.","romaji":"Kanojo ni tegami wo agetai."}],"example":"プレゼントをあげる。","exampleMeaning":"I give a present."},{"pattern":"Nounをいただく","meaning":"To receive or accept something politely; 'to receive', 'to get', 'to accept'.","formation":"Noun + を + いただく","examples":[{"jp":"プレゼントをいただきありがとうございます。","en":"Thank you for the gift that I received.","romaji":"Purezento wo itadaki arigatou gozaimasu."},{"jp":"先生からアドバイスをいただきました。","en":"I received advice from my teacher.","romaji":"Sensei kara adobaisu wo itadakimashita."},{"jp":"このコーヒーをいただいていいですか？","en":"May I have this coffee?","romaji":"Kono koohii wo itadaite ii desu ka?"},{"jp":"会社の上司に昇進のお知らせをいただきました。","en":"I received a promotion notification from my boss at the company.","romaji":"Kaisha no joushi ni shoushin no oshirase wo itadakimashita."}],"example":"プレゼントをいただきありがとうございます。","exampleMeaning":"Thank you for the gift that I received."},{"pattern":"Nounをくださる","meaning":"Used to express someone doing something as a favor or for the benefit of the speaker.","formation":"Noun + を + くださる","examples":[{"jp":"先生が資料をくださった。","en":"The teacher gave me the materials.","romaji":"Sensei ga shiryou wo kudasatta."},{"jp":"お母さんがおやつをくださる。","en":"My mother gives me snacks.","romaji":"Okaasan ga oyatsu wo kudasaru."},{"jp":"上司がアドバイスをくださいました。","en":"My boss gave me advice.","romaji":"Joushi ga adobaisu wo kudasaimashita."},{"jp":"友達がプレゼントをくださった。","en":"My friend gave me a present.","romaji":"Tomodachi ga purezento wo kudasatta."}],"example":"先生が資料をくださった。","exampleMeaning":"The teacher gave me the materials."},{"pattern":"Noun を くれる","meaning":"Expresses that someone gives a thing to the speaker or someone close to the speaker.","formation":"Giver + が + Receiver + に + Noun + を + くれる","examples":[{"jp":"友達が私にプレゼントをくれました。","en":"My friend gave me a present.","romaji":"Tomodachi ga watashi ni purezento wo kuremashita."},{"jp":"彼が私に花をくれた。","en":"He gave me flowers.","romaji":"Kare ga watashi ni hana wo kureta."},{"jp":"先生が私に本をくれました。","en":"The teacher gave me a book.","romaji":"Sensei ga watashi ni hon wo kuremashita."},{"jp":"お母さんが弟にお菓子をくれました。","en":"Mom gave my little brother some sweets.","romaji":"Okaasan ga otouto ni okashi wo kuremashita."}],"example":"友達が私にプレゼントをくれました。","exampleMeaning":"My friend gave me a present."},{"pattern":"Noun を さしあげる","meaning":"A polite way of expressing to give something.","formation":"Noun + を + さしあげる","examples":[{"jp":"先生に本をさしあげます。","en":"I will give a book to the teacher.","romaji":"Sensei ni hon wo sashiagemasu."},{"jp":"お母さんに花をさしあげたいです。","en":"I want to give flowers to my mother.","romaji":"Okaasan ni hana wo sashiagetai desu."},{"jp":"お客様にお茶をさしあげましょう。","en":"Let's offer tea to the guest.","romaji":"Okyakusama ni ocha wo sashiagemashou."},{"jp":"先輩にプレゼントをさしあげたら、喜んでいました。","en":"When I gave a present to my senior, they were delighted.","romaji":"Senpai ni purezento wo sashiagetara, yorokonde imashita."}],"example":"先生に本をさしあげます。","exampleMeaning":"I will give a book to the teacher."},{"pattern":"Noun もらう","meaning":"To receive or get something from someone; 'to receive', 'to get'.","formation":"Noun + を + もらう","examples":[{"jp":"友達からプレゼントをもらいました。","en":"I received a gift from my friend.","romaji":"Tomodachi kara purezento wo moraimashita."},{"jp":"先生にアドバイスをもらいました。","en":"I got advice from my teacher.","romaji":"Sensei ni adobaisu wo moraimashita."},{"jp":"お父さんからお小遣いをもらう。","en":"To receive an allowance from one's father.","romaji":"Otousan kara okozukai wo morau."},{"jp":"彼女に手紙をもらった。","en":"I got a letter from her.","romaji":"Kanojo ni tegami wo moratta."}],"example":"友達からプレゼントをもらいました。","exampleMeaning":"I received a gift from my friend."},{"pattern":"Noun + 中 (Noun + ちゅう)","meaning":"Express 'in the middle of', 'during', or 'in the process of'.","formation":"Noun + 中 (ちゅう)","examples":[{"jp":"彼は仕事中です。","en":"He is in the middle of work.","romaji":"Kare wa shigotochuu desu."},{"jp":"試験中、携帯電話を使ってはいけません。","en":"During the exam, you must not use your mobile phone.","romaji":"Shiken chuu, keitai denwa wo tsukatte wa ikemasen."},{"jp":"映画を観ている最中に、彼は泣き始めました。","en":"In the middle of watching the movie, he started to cry.","romaji":"Eiga o mite iru saichuu ni, kare wa naki hajimemashita."},{"jp":"彼女は今勉強中です。","en":"She is currently studying.","romaji":"Kanojo wa ima benkyouchuu desu."}],"example":"彼は仕事中です。","exampleMeaning":"He is in the middle of work."},{"pattern":"Verb させられる (Verb-saserareru)","meaning":"Express the passive causative form; 'to be made to', 'to be forced to'.","formation":"Group 1 Verb: Replace ～う with ～わせられる, Group 2 Verb: Replace ～る with ～させられる, Group 3 Verb: する → させられる, くる → こさせられる","examples":[{"jp":"子供たちは先生に宿題をやらせられました。","en":"The children were made to do their homework by the teacher.","romaji":"Kodomo-tachi wa sensei ni shukudai wo yaraseraremashita."},{"jp":"彼は会社にもっと働かせられた。","en":"He was forced to work more by the company.","romaji":"Kare wa kaisha ni motto hatarakaserareta."},{"jp":"私は友達にその機密を話させられました。","en":"I was made to reveal that secret by my friend.","romaji":"Watashi wa tomodachi ni sono kimitsu o hanasaseraremashita."},{"jp":"怪我をした選手は、コーチに休ませられました。","en":"The injured player was forced to rest by the coach.","romaji":"Kega wo shita senshu wa, kouchi ni yasumaseraremashita."}],"example":"子供たちは先生に宿題をやらせられました。","exampleMeaning":"The children were made to do their homework by the teacher."},{"pattern":"Verb させる (Verb-saseru)","meaning":"Expresses 'to make someone do something', 'to let someone do something', or 'to cause someone to do something'.","formation":"Group 1 Verbs: Change the last hiragana to ～せる, Group 2 Verbs: Remove ～る and add ～させる, Group 3 Verbs: する → させる, くる → こさせる","examples":[{"jp":"先生が生徒に宿題をさせました。","en":"The teacher made the students do homework.","romaji":"Sensei ga seito ni shukudai o sasemashita."},{"jp":"母が私に部屋を掃除させました。","en":"My mother made me clean my room.","romaji":"Haha ga watashi ni heya o souji sasemashita."},{"jp":"彼女にピアノを弾かせてあげました。","en":"I let her play the piano.","romaji":"Kanojo ni piano o hikasete agemashita."},{"jp":"上司は彼にそのプログラムを作らせました。","en":"The boss made him create the program.","romaji":"Joushi wa kare ni sono puroguramu o tsukurasemashita."}],"example":"先生が生徒に宿題をさせました。","exampleMeaning":"The teacher made the students do homework."},{"pattern":"Verb た ことがある","meaning":"Expresses the experience of having done something in the past.","formation":"Verb-た-form + ことがある","examples":[{"jp":"日本に行ったことがあります。","en":"I have been to Japan before.","romaji":"Nihon ni itta koto ga arimasu."},{"jp":"寿司を食べたことがありますか？","en":"Have you ever eaten sushi before?","romaji":"Sushi wo tabeta koto ga arimasu ka?"},{"jp":"彼はマラソンを走ったことがあります。","en":"He has experienced running a marathon.","romaji":"Kare wa marason wo hashitta koto ga arimasu."},{"jp":"私はスカイダイビングをしたことがありません。","en":"I have never experienced skydiving.","romaji":"Watashi wa sukaidaibingu wo shita koto ga arimasen."}],"example":"日本に行ったことがあります。","exampleMeaning":"I have been to Japan before."},{"pattern":"Verb た ときに","meaning":"Express an action or event that occurred at a specific time in the past; 'when', 'at the time'.","formation":"Verb-た + ときに","examples":[{"jp":"映画を見たときに、泣きました。","en":"When I watched the movie, I cried.","romaji":"Eiga wo mita toki ni, nakimashita."},{"jp":"彼に初めて会ったときに、遅刻していました。","en":"When I first met him, he was late.","romaji":"Kare ni hajimete atta toki ni, chikoku shite imashita."},{"jp":"日本へ行ったときに、たくさんの写真を撮りました。","en":"When I went to Japan, I took a lot of photos.","romaji":"Nihon e itta toki ni, takusan no shashin wo torimashita."},{"jp":"友達が家に来たときに、ゲームをしました。","en":"When my friend came to my house, we played games.","romaji":"Tomodachi ga ie ni kita toki ni, geemu wo shimashita."}],"example":"映画を見たときに、泣きました。","exampleMeaning":"When I watched the movie, I cried."},{"pattern":"Verb た ところ","meaning":"Expresses the situation right after an action has taken place.","formation":"Verb (た form) + ところ","examples":[{"jp":"ドアを開けたところ、猫が飛び出してきた。","en":"When I opened the door, a cat came jumping out.","romaji":"Doa wo aketa tokoro, neko ga tobidashite kita."},{"jp":"電話を切ったところ、また鳴った。","en":"Right after I hung up the phone, it rang again.","romaji":"Denwa wo kitta tokoro, mata natta."},{"jp":"宿題を終わらせたところで、友達から連絡が来た。","en":"Just as I finished my homework, I got a message from my friend.","romaji":"Shukudai wo owaraseta tokoro de, tomodachi kara renraku ga kita."},{"jp":"買い物をして帰ったところ、財布を失くしたことに気づいた。","en":"After shopping and returning home, I realized I had lost my wallet.","romaji":"Kaimono wo shite kaetta tokoro, saifu wo nakushita koto ni kizuita."}],"example":"ドアを開けたところ、猫が飛び出してきた。","exampleMeaning":"When I opened the door, a cat came jumping out."},{"pattern":"Verb たほうがいい (〜ta hou ga ii)","meaning":"Used to give advice or make a suggestion to someone - 'it's better if...'.","formation":"Verb (past tense) + ほうがいい","examples":[{"jp":"早く寝たほうがいい。","en":"It's better if you go to bed early.","romaji":"Hayaku neta hou ga ii."},{"jp":"もっと勉強したほうがいい。","en":"You should study more.","romaji":"Motto benkyou shita hou ga ii."},{"jp":"病気の時は、薬を飲んだほうがいい。","en":"It's a good idea to take medicine when you're sick.","romaji":"Byouki no toki wa, kusuri wo nonda hou ga ii."},{"jp":"コーヒーを飲まないほうがいい。","en":"It's better if you don't drink coffee.","romaji":"Koohii wo nomanai hou ga ii."}],"example":"早く寝たほうがいい。","exampleMeaning":"It's better if you go to bed early."},{"pattern":"Verb ために","meaning":"Used to describe the purpose or reason for an action; 'for the sake of', 'in order to', 'because of'.","formation":"1) Verb (dictionary form) + ために (purpose)\n2) い-Adjective + ために (reason)\n3) な-Adjective + な + ために (reason)\n4) Noun + の + ために (reason)","examples":[{"jp":"試験に合格するために、毎日勉強しています。","en":"I study every day in order to pass the exam.","romaji":"Shiken ni goukaku suru tame ni, mainichi benkyou shiteimasu."},{"jp":"健康のために、毎日運動しなければなりません。","en":"For the sake of health, I must exercise daily.","romaji":"Kenkou no tame ni, mainichi undou shinakereba narimasen."},{"jp":"仕事が忙しいために、友達と会う時間がありません。","en":"Because my work is busy, I don't have time to meet friends.","romaji":"Shigoto ga isogashii tame ni, tomodachi to au jikan ga arimasen."},{"jp":"雨が降ったために、試合が中止されました。","en":"The game was canceled because of the rain.","romaji":"Ame ga futta tame ni, shiai ga chuushi saremashita."}],"example":"試験に合格するために、毎日勉強しています。","exampleMeaning":"I study every day in order to pass the exam."},{"pattern":"Verb つもり (〜tsumori)","meaning":"Express the intention, plan, or determination to do something; 'I intend to', 'I plan to', 'I'm determined to'.","formation":"Verb-casual + つもり","examples":[{"jp":"明日、友達に会うつもりです。","en":"I plan to meet my friend tomorrow.","romaji":"Ashita, tomodachi ni au tsumori desu."},{"jp":"今夜、晩ご飯を作るつもりです。","en":"I intend to cook dinner tonight.","romaji":"Konya, bangohan o tsukuru tsumori desu."},{"jp":"来年、留学するつもりです。","en":"I plan to study abroad next year.","romaji":"Rainen, ryuugaku suru tsumori desu."},{"jp":"この週末、山に登るつもりです。","en":"I'm determined to climb the mountain this weekend.","romaji":"Kono shuumatsu, yama ni noboru tsumori desu."}],"example":"明日、友達に会うつもりです。","exampleMeaning":"I plan to meet my friend tomorrow."},{"pattern":"Verb てあげる","meaning":"Used to express doing something for someone; 'do something for someone'.","formation":"Verb-て form + あげる","examples":[{"jp":"友達が疲れていたから、荷物を持ってあげた。","en":"Since my friend was tired, I carried their luggage for them.","romaji":"Tomodachi ga tsukareteita kara, nimotsu o motte ageta."},{"jp":"弟は宿題がわからなかったので、手伝ってあげた。","en":"My younger brother couldn't understand the homework, so I helped him.","romaji":"Otouto wa shukudai ga wakaranakatta node, tetsudatte ageta."},{"jp":"彼女が遅れそうだったから、駅まで迎えに行ってあげた。","en":"She was running late, so I went to pick her up at the station.","romaji":"Kanojo ga okuresou datta kara, eki made mukae ni itte ageta."},{"jp":"犬はのどが渇いたそうだったので、水を飲ませてあげた。","en":"The dog seemed thirsty, so I gave it water to drink.","romaji":"Inu wa nodo ga kawaita sou datta node, mizu o nomasete ageta."}],"example":"友達が疲れていたから、荷物を持ってあげた。","exampleMeaning":"Since my friend was tired, I carried their luggage for them."},{"pattern":"Verb て ある (Verb-te aru)","meaning":"Indicates that an action has been done and its result is still in effect.","formation":"Verb-て form + ある","examples":[{"jp":"窓が開けてある。","en":"The window has been opened (and remains open).","romaji":"Mado ga akete aru."},{"jp":"宿題がもう終わってある。","en":"The homework has already been done (and remains that way).","romaji":"Shukudai ga mou owatte aru."},{"jp":"洗濯物が全部干してある。","en":"The laundry has been hung up to dry (and remains that way).","romaji":"Sentakumono ga zenbu hoshite aru."},{"jp":"この部屋はきれいに掃除してある。","en":"This room has been cleaned (and remains clean).","romaji":"Kono heya wa kirei ni souji shite aru."}],"example":"窓が開けてある。","exampleMeaning":"The window has been opened (and remains open)."},{"pattern":"Verb て いく (Verb-te iku)","meaning":"Expresses an action that continues on into the future or a change that progresses over time.","formation":"Verb in て-form + いく","examples":[{"jp":"このまま練習を続けていくと、上達するでしょう。","en":"If you keep practicing like this, you will improve.","romaji":"Kono mama renshuu o tsuzukete iku to, joutatsu suru deshou."},{"jp":"彼は成長していくうちに、自立心が強くなった。","en":"As he grew up, his independence became stronger.","romaji":"Kare wa seichou shite iku uchi ni, jiritsushin ga tsuyoku natta."},{"jp":"この会社はこれからも技術革新を行っていくでしょう。","en":"This company will continue to innovate in technology in the future.","romaji":"Kono kaisha wa korekara mo gijutsu kakushin o okonatte iku deshou."},{"jp":"子供たちはどんどん学んでいく。","en":"Children will keep learning more and more.","romaji":"Kodomo-tachi wa dondon manande iku."}],"example":"このまま練習を続けていくと、上達するでしょう。","exampleMeaning":"If you keep practicing like this, you will improve."},{"pattern":"Verb ていただきたい","meaning":"Express a polite request or desire that someone does something for you.","formation":"Verb-て form + いただきたい","examples":[{"jp":"資料をコピーしていただきたいです。","en":"I would like you to make copies of the documents.","romaji":"Shiryou wo kopii shite itadakitai desu."},{"jp":"この仕事を手伝っていただきたいのですが。","en":"I would like to ask for your assistance with this work.","romaji":"Kono shigoto wo tetsudatte itadakitai no desu ga."},{"jp":"もしよろしければ、指導していただきたいです。","en":"If it is not too much trouble, I would like you to guide me.","romaji":"Moshi yoroshikereba, shidou shite itadakitai desu."},{"jp":"駅まで送っていただきたいんですが。","en":"I was wondering if you could give me a ride to the station.","romaji":"Eki made okutte itadakitain desu ga."}],"example":"資料をコピーしていただきたいです。","exampleMeaning":"I would like you to make copies of the documents."},{"pattern":"Verb ていただく (〜te itadaku)","meaning":"Used to express receiving someone's favor or help; 'to kindly do'.","formation":"Verb-て form + いただく","examples":[{"jp":"メールを送っていただいて、ありがとうございます。","en":"Thank you for kindly sending the email.","romaji":"Meeru o okutte itadaite, arigatou gozaimasu."},{"jp":"荷物を運んでいただいて、助かりました。","en":"You really helped me by carrying the luggage.","romaji":"Nimotsu o hakonde itadaite, tasukarimashita."},{"jp":"資料をチェックしていただきたいです。","en":"I would like you to kindly check the documents.","romaji":"Shiryou o chekku shite itadakitai desu."},{"jp":"先生にアドバイスをしていただきました。","en":"The teacher kindly gave me advice.","romaji":"Sensei ni adobaisu o shite itadakimashita."}],"example":"メールを送っていただいて、ありがとうございます。","exampleMeaning":"Thank you for kindly sending the email."},{"pattern":"Verb て いただけませんか","meaning":"A polite request; 'Could you please...', 'Would you mind...'","formation":"Verb-て form + いただけませんか","examples":[{"jp":"この手紙を投函していただけませんか。","en":"Could you please mail this letter for me?","romaji":"Kono tegami wo toukan shite itadakemasen ka."},{"jp":"この荷物を持っていただけませんか。","en":"Could you please carry this luggage for me?","romaji":"Kono nimotsu wo motte itadakemasen ka."},{"jp":"隣の部屋にいる人に静かにしていただけませんか。","en":"Could you please ask the person next door to be quiet?","romaji":"Tonari no heya ni iru hito ni shizuka ni shite itadakemasen ka."},{"jp":"説明書を読んでいただけませんか。","en":"Could you please read the instruction manual?","romaji":"Setsumeisho wo yonde itadakemasen ka."}],"example":"この手紙を投函していただけませんか。","exampleMeaning":"Could you please mail this letter for me?"},{"pattern":"Verb て いる (Verb-te iru)","meaning":"Expresses an ongoing action or a state resulting from a past action.","formation":"Verb (て-form) + いる","examples":[{"jp":"今、本を読んでいます。","en":"I am reading a book now.","romaji":"Ima, hon wo yonde imasu."},{"jp":"彼は英語を勉強しています。","en":"He is studying English.","romaji":"Kare wa eigo wo benkyou shite imasu."},{"jp":"ケーキが冷蔵庫に入っています。","en":"The cake is in the refrigerator.","romaji":"Keeki ga reizouko ni haitte imasu."},{"jp":"部屋がきれいになっています。","en":"The room has become clean.","romaji":"Heya ga kirei ni natte imasu."}],"example":"今、本を読んでいます。","exampleMeaning":"I am reading a book now."},{"pattern":"Verb て いる ところ","meaning":"Describes an action that is currently happening; 'in the middle of', 'in the process of'.","formation":"Verb-て form + いる ところ","examples":[{"jp":"彼は宿題をしているところです。","en":"He is in the middle of doing his homework.","romaji":"Kare wa shukudai wo shite iru tokoro desu."},{"jp":"私たちは映画を見ているところでした。","en":"We were in the process of watching a movie.","romaji":"Watashitachi wa eiga wo mite iru tokoro deshita."},{"jp":"子供たちは公園で遊んでいるところです。","en":"The kids are in the middle of playing in the park.","romaji":"Kodomotachi wa kouen de asonde iru tokoro desu."},{"jp":"彼女はケーキを作っているところで、すぐ来ます。","en":"She is in the process of making a cake and will come soon.","romaji":"Kanojo wa keeki wo tsukutte iru tokoro de, sugu kimasu."}],"example":"彼は宿題をしているところです。","exampleMeaning":"He is in the middle of doing his homework."},{"pattern":"Verb ている間に","meaning":"Expresses 'while' or 'during the time' something is happening.","formation":"Verb-て form + いる + 間に","examples":[{"jp":"映画を見ている間に、彼は寝てしまった。","en":"While watching the movie, he fell asleep.","romaji":"Eiga o mite iru aida ni, kare wa nete shimatta."},{"jp":"子供が遊んでいる間に、私は料理を作ります。","en":"While the children are playing, I'll cook.","romaji":"Kodomo ga asonde iru aida ni, watashi wa ryouri o tsukurimasu."},{"jp":"会議が行われている間に、雨が降り始めた。","en":"While the meeting was being held, it started raining.","romaji":"Kaigi ga okonawarete iru aida ni, ame ga furihajimeta."},{"jp":"彼が仕事をしている間に、私たちは買い物に行く。","en":"While he is working, we'll go shopping.","romaji":"Kare ga shigoto o shite iru aida ni, watashitachi wa kaimono ni iku."}],"example":"映画を見ている間に、彼は寝てしまった。","exampleMeaning":"While watching the movie, he fell asleep."},{"pattern":"Verb ておく (〜te oku)","meaning":"Perform an action in preparation for a future situation; 'to do something in advance'.","formation":"Verb-て form + おく","examples":[{"jp":"駅で切符を買っておこう。","en":"Let's buy the tickets in advance at the station.","romaji":"Eki de kippu wo katte okou."},{"jp":"明日早く起きるために、今晩早く寝ておきます。","en":"I will go to bed early tonight to wake up early tomorrow.","romaji":"Ashita hayaku okiru tame ni, konban hayaku nete okimasu."},{"jp":"試験前に勉強しておかないと、失敗するかもしれない。","en":"If I don't study in advance before the exam, I might fail.","romaji":"Shiken mae ni benkyou shite okanai to, shippai suru kamo shirenai."},{"jp":"彼が到着する前に、部屋をきれいに掃除しておきましょう。","en":"Let's clean the room before he arrives.","romaji":"Kare ga touchaku suru mae ni, heya wo kirei ni souji shite okimashou."}],"example":"駅で切符を買っておこう。","exampleMeaning":"Let's buy the tickets in advance at the station."},{"pattern":"Verb て くださいませんか (Verb-te kudasaimasen ka)","meaning":"Polite request for asking someone for a favor.","formation":"Verb in て-form + くださいませんか","examples":[{"jp":"コーヒーを飲んでくださいませんか。","en":"Would you please drink some coffee?","romaji":"Koohii o nonde kudasaimasen ka."},{"jp":"ドアを閉めてくださいませんか。","en":"Would you please close the door?","romaji":"Doa o shimete kudasaimasen ka."},{"jp":"明日お昼に会ってくださいませんか。","en":"Would you please meet me at lunch tomorrow?","romaji":"Ashita ohiru ni atte kudasaimasen ka."},{"jp":"その資料を送ってくださいませんか。","en":"Would you please send me that document?","romaji":"Sono shiryou o okutte kudasaimasen ka."}],"example":"コーヒーを飲んでくださいませんか。","exampleMeaning":"Would you please drink some coffee?"},{"pattern":"Verb て くださる (Verb-te kudasaru)","meaning":"Expresses gratitude for receiving someone's favor; 'to kindly do'.","formation":"Verb て-form + くださる","examples":[{"jp":"先生が手伝ってくださる。","en":"The teacher kindly helps.","romaji":"Sensei ga tetsudatte kudasaru."},{"jp":"お母さんが美味しい料理を作ってくださる。","en":"My mother kindly cooks delicious meals.","romaji":"Okaasan ga oishii ryouri wo tsukutte kudasaru."},{"jp":"友達が私を駅まで送ってくださる。","en":"My friend kindly gives me a ride to the station.","romaji":"Tomodachi ga watashi wo eki made okutte kudasaru."},{"jp":"部長がすぐに質問に答えてくださる。","en":"The manager kindly answers the questions immediately.","romaji":"Buchou ga sugu ni shitsumon ni kotaete kudasaru."}],"example":"先生が手伝ってくださる。","exampleMeaning":"The teacher kindly helps."},{"pattern":"Verb て くる","meaning":"An action that starts in the past and continues to the present or future; 'come to', 'begin to', 'become'.","formation":"Verb て-form + くる","examples":[{"jp":"最近、日本語が分かってくるようになりました。","en":"Recently, I've come to understand Japanese.","romaji":"Saikin, nihongo ga wakatte kuru you ni narimashita."},{"jp":"寒くなってきたので、コートを着ましょう。","en":"Since it's gotten cold, let's put on a coat.","romaji":"Samuku natte kita node, kooto wo kimashou."},{"jp":"雨がやんできました。","en":"The rain has stopped (and it's cleared up).","romaji":"Ame ga yande kimashita."},{"jp":"彼がだんだん怖くなってきた。","en":"He has become progressively scarier.","romaji":"Kare ga dandan kowaku natte kita."}],"example":"最近、日本語が分かってくるようになりました。","exampleMeaning":"Recently, I've come to understand Japanese."},{"pattern":"Verb てくれませんか (〜te kuremasen ka)","meaning":"A polite way to request someone to do something for you; 'Could you please', 'Would you please', 'Won't you'.","formation":"Verb-て form + くれませんか","examples":[{"jp":"ドアを開けてくれませんか。","en":"Could you please open the door?","romaji":"Doa wo akete kuremasen ka."},{"jp":"これを見てくれませんか。","en":"Would you please take a look at this?","romaji":"Kore wo mite kuremasen ka."},{"jp":"手伝ってくれませんか。","en":"Won't you help me?","romaji":"Tetsudatte kuremasen ka."},{"jp":"明日、迎えに来てくれませんか。","en":"Could you please come to pick me up tomorrow?","romaji":"Ashita, mukae ni kite kuremasen ka."}],"example":"ドアを開けてくれませんか。","exampleMeaning":"Could you please open the door?"},{"pattern":"Verb て くれる (Verb-te kureru)","meaning":"Expresses that someone does something for the speaker (or another person in speaker's group); 'to do something for me/us'.","formation":"Verb-te form + くれる","examples":[{"jp":"友達が宿題を手伝ってくれました。","en":"My friend helped me with my homework.","romaji":"Tomodachi ga shukudai wo tetsudatte kuremashita."},{"jp":"弟が部屋を掃除してくれた。","en":"My younger brother cleaned the room for me.","romaji":"Otouto ga heya wo souji shite kureta."},{"jp":"先生が質問に答えてくれます。","en":"The teacher answers my questions for me.","romaji":"Sensei ga shitsumon ni kotaete kuremasu."},{"jp":"彼女が手紙を書いてくれる。","en":"She writes a letter for me.","romaji":"Kanojo ga tegami wo kaite kureru."}],"example":"友達が宿題を手伝ってくれました。","exampleMeaning":"My friend helped me with my homework."},{"pattern":"Verb て + さしあげる","meaning":"A polite way to express giving or doing something for someone.","formation":"Verb-てform + さしあげる","examples":[{"jp":"お茶を入れてさしあげます。","en":"I will prepare and serve tea (for you).","romaji":"Ocha wo irete sashiagemasu."},{"jp":"メッセージを送ってさしあげました。","en":"I have sent the message (for you).","romaji":"Messeiji wo okutte sashiagemashita."},{"jp":"荷物を持ってさしあげましょうか。","en":"Shall I carry the luggage (for you)?","romaji":"Nimotsu wo motte sashiagemashou ka."},{"jp":"お電話をかけてさしあげます。","en":"I will make a phone call (for you).","romaji":"Odenwa wo kakete sashiagemasu."}],"example":"お茶を入れてさしあげます。","exampleMeaning":"I will prepare and serve tea (for you)."},{"pattern":"Verb てしまう (〜te shimau)","meaning":"Expresses unintentional actions or actions with regrettable outcomes; 'to end up doing', 'to accidentally do'.","formation":"Verb-te form + しまう","examples":[{"jp":"ケーキを全部食べてしまった。","en":"I ended up eating the whole cake.","romaji":"Keeki wo zenbu tabete shimatta."},{"jp":"宿題を忘れてしまいました。","en":"I accidentally forgot my homework.","romaji":"Shukudai wo wasurete shimaimashita."},{"jp":"彼に秘密を言ってしまった。","en":"I accidentally told him the secret.","romaji":"Kare ni himitsu wo itte shimatta."},{"jp":"値札を見ずに高い服を買ってしまった。","en":"I ended up buying expensive clothes without looking at the price tag.","romaji":"Nefuda wo mizu ni takai fuku wo katte shimatta."}],"example":"ケーキを全部食べてしまった。","exampleMeaning":"I ended up eating the whole cake."},{"pattern":"Verb て ほしい (Verb-te hoshii)","meaning":"Express a desire for someone else to do something; 'I want (someone) to'.","formation":"Verb-て form + ほしい","examples":[{"jp":"子供にもっと勉強してほしい。","en":"I want my child to study more.","romaji":"Kodomo ni motto benkyou shite hoshii."},{"jp":"彼にもっと早く来てほしい。","en":"I want him to come earlier.","romaji":"Kare ni motto hayaku kite hoshii."},{"jp":"友達にその本を読んでほしい。","en":"I want my friend to read that book.","romaji":"Tomodachi ni sono hon o yonde hoshii."},{"jp":"先生に質問に答えてほしい。","en":"I want the teacher to answer the question.","romaji":"Sensei ni shitsumon ni kotaete hoshii."}],"example":"子供にもっと勉強してほしい。","exampleMeaning":"I want my child to study more."},{"pattern":"Verb てみる (〜te miru)","meaning":"Used to express 'try to' or 'attempt to do'.","formation":"Verb-て form + みる","examples":[{"jp":"この料理を作ってみます。","en":"I will try to make this dish.","romaji":"Kono ryouri o tsukutte mimasu."},{"jp":"その服を着てみてください。","en":"Please try on those clothes.","romaji":"Sono fuku o kite mite kudasai."},{"jp":"新しいレストランに行ってみよう。","en":"Let's try going to the new restaurant.","romaji":"Atarashii resutoran ni itte miyou."},{"jp":"映画を見てみたいです。","en":"I want to try watching the movie.","romaji":"Eiga o mite mitai desu."}],"example":"この料理を作ってみます。","exampleMeaning":"I will try to make this dish."},{"pattern":"Verb てもらいたい","meaning":"Express a desire to receive a favor or service from someone else.","formation":"Verb-て-form + もらいたい","examples":[{"jp":"この荷物を運んでもらいたいです。","en":"I want you to carry this luggage for me.","romaji":"Kono nimotsu o hakonde moraitai desu."},{"jp":"彼にそのニュースを教えてもらいたい。","en":"I want him to tell me the news.","romaji":"Kare ni sono nyuusu o oshiete moraitai."},{"jp":"友達に日本語を教えてもらいたい。","en":"I want my friend to teach me Japanese.","romaji":"Tomodachi ni Nihongo o oshiete moraitai."},{"jp":"スタッフにチェックインの方法を説明してもらいたい。","en":"I want the staff to explain the check-in process to me.","romaji":"Sutaffu ni chekkuin no houhou o setsumei shite moraitai."}],"example":"この荷物を運んでもらいたいです。","exampleMeaning":"I want you to carry this luggage for me."},{"pattern":"Verb て もらう (Verb-te morau)","meaning":"Express receiving a favor or action from someone.","formation":"Verb-て form + もらう","examples":[{"jp":"友達に宿題を手伝ってもらった。","en":"I had my friend help me with my homework.","romaji":"Tomodachi ni shukudai o tetsudatte moratta."},{"jp":"母に部屋を掃除してもらいました。","en":"I had my mother clean my room.","romaji":"Haha ni heya o souji shite moraimashita."},{"jp":"彼に荷物を持ってもらいたい。","en":"I want him to carry my luggage for me.","romaji":"Kare ni nimotsu o motte moraitai."},{"jp":"先生に質問に答えてもらえますか？","en":"Can I have the teacher answer my question?","romaji":"Sensei ni shitsumon ni kotaete moraemasu ka?"}],"example":"友達に宿題を手伝ってもらった。","exampleMeaning":"I had my friend help me with my homework."},{"pattern":"Verb てもらえませんか","meaning":"A polite way to ask for a favor or request someone to do something.","formation":"Verb-て form + もらえませんか","examples":[{"jp":"この手紙を見てもらえませんか。","en":"Could you take a look at this letter for me?","romaji":"Kono tegami o mite moraemasen ka?"},{"jp":"荷物を持ってもらえませんか。","en":"Could you carry this luggage for me?","romaji":"Nimotsu o motte moraemasen ka?"},{"jp":"部屋を掃除してもらえませんか。","en":"Could you clean the room for me?","romaji":"Heya o souji shite moraemasen ka?"},{"jp":"明日のミーティングに参加してもらえませんか。","en":"Could you attend tomorrow's meeting for me?","romaji":"Ashita no miitingu ni sanka shite moraemasen ka?"}],"example":"この手紙を見てもらえませんか。","exampleMeaning":"Could you take a look at this letter for me?"},{"pattern":"Verb ない ことがある (Verb-nai koto ga aru)","meaning":"Expresses that something doesn't always happen or there are occasions when it doesn't happen.","formation":"Verb-negative form + ことがある","examples":[{"jp":"彼は会議に出席しないことがある。","en":"There are times when he doesn't attend meetings.","romaji":"Kare wa kaigi ni shusseki shinai koto ga aru."},{"jp":"この電車は定刻に来ないことがある。","en":"There are occasions when this train doesn't come on time.","romaji":"Kono densha wa teikoku ni konai koto ga aru."},{"jp":"私は朝食を食べないことがある。","en":"There are times when I don't eat breakfast.","romaji":"Watashi wa choushoku o tabenai koto ga aru."},{"jp":"彼女は電話に出ないことがある。","en":"There are occasions when she doesn't answer the phone.","romaji":"Kanojo wa denwa ni denai koto ga aru."}],"example":"彼は会議に出席しないことがある。","exampleMeaning":"There are times when he doesn't attend meetings."},{"pattern":"Verb ない + ことにする","meaning":"To decide not to do something.","formation":"Verb-ない form + ことにする","examples":[{"jp":"明日のパーティーに行かないことにする。","en":"I've decided not to go to tomorrow's party.","romaji":"Ashita no paatii ni ikanai koto ni suru."},{"jp":"そのケーキを食べないことにします。","en":"I've decided not to eat that cake.","romaji":"Sono keeki wo tabenai koto ni shimasu."},{"jp":"今日はジョギングをしないことにする。","en":"I've decided not to go jogging today.","romaji":"Kyou wa jogingu wo shinai koto ni suru."},{"jp":"彼と会わないことにしました。","en":"I've decided not to meet him.","romaji":"Kare to awanai koto ni shimashita."}],"example":"明日のパーティーに行かないことにする。","exampleMeaning":"I've decided not to go to tomorrow's party."},{"pattern":"Verb ない ことになる","meaning":"Expresses a result; 'end up not', 'it will become that', 'it would mean that'.","formation":"Verb-negative (ない) + ことになる","examples":[{"jp":"今日彼が来ないことになると、私たちの予定はキャンセルされます。","en":"If he doesn't come today, our plans will be canceled.","romaji":"Kyou kare ga konai koto ni naru to, watashitachi no yotei wa kyanseru saremasu."},{"jp":"このプロジェクトが進まないことになると、収益が減るでしょう。","en":"If this project doesn't progress, it would mean that revenue will decrease.","romaji":"Kono purojekuto ga susumanai koto ni naru to, shuueki ga heru deshou."},{"jp":"彼女は試験に合格しないことになると、卒業が遅れます。","en":"If she ends up not passing the exam, her graduation will be delayed.","romaji":"Kanojo wa shiken ni goukaku shinai koto ni naru to, sotsugyou ga okuremasu."},{"jp":"雨が降ると、ピクニックが行われないことになるでしょう。","en":"If it rains, it will become that the picnic doesn't take place.","romaji":"Ame ga furu to, pikunikku ga okonawarenai koto ni naru deshou."}],"example":"今日彼が来ないことになると、私たちの予定はキャンセルされます。","exampleMeaning":"If he doesn't come today, our plans will be canceled."},{"pattern":"Verb ないほうがいい","meaning":"Expresses the idea that it is better not to do something.","formation":"Verb-negative form + ほうがいい","examples":[{"jp":"この薬は飲まないほうがいいです。","en":"It's better not to take this medicine.","romaji":"Kono kusuri wa nomanai hou ga ii desu."},{"jp":"急いでいるときは、走らないほうがいい。","en":"When you're in a hurry, it's better not to run.","romaji":"Isoide iru toki wa, hashiranai hou ga ii."},{"jp":"彼に秘密を知られたくなければ、話さないほうがいい。","en":"If you don't want him to know your secret, it's better not to tell him.","romaji":"Kare ni himitsu o shiraretakunakereba, hanasanai hou ga ii."},{"jp":"雨の日には、外出しないほうがいい。","en":"It's better not to go out on a rainy day.","romaji":"Ame no hi ni wa, gaishutsu shinai hou ga ii."}],"example":"この薬は飲まないほうがいいです。","exampleMeaning":"It's better not to take this medicine."},{"pattern":"Verb ながら (〜nagara)","meaning":"Expresses 'while' or 'as' in the sense of doing two things simultaneously.","formation":"Verb-masu stem + ながら","examples":[{"jp":"テレビを見ながら宿題をしました。","en":"I did my homework while watching television.","romaji":"Terebi wo minagara shukudai wo shimashita."},{"jp":"音楽を聞きながら料理をしました。","en":"I cooked while listening to music.","romaji":"Ongaku wo kikinagara ryouri wo shimashita."},{"jp":"歩きながらスマホを見るのは危険です。","en":"Looking at your smartphone while walking is dangerous.","romaji":"Arukinagara sumaho wo miru no wa kiken desu."},{"jp":"彼は話しながら笑っていました。","en":"He was laughing while talking.","romaji":"Kare wa hanashi nagara waratte imashita."}],"example":"テレビを見ながら宿題をしました。","exampleMeaning":"I did my homework while watching television."},{"pattern":"Verb なさい (〜nasai)","meaning":"A command form used to give orders or instructions; 'Please do', 'Do this'.","formation":"Verb-stem + なさい","examples":[{"jp":"部屋を掃除しなさい。","en":"Clean your room.","romaji":"Heya wo souji shinasai."},{"jp":"勉強しなさい。","en":"Study.","romaji":"Benkyou shinasai."},{"jp":"早く起きなさい。","en":"Wake up early.","romaji":"Hayaku okinasai."},{"jp":"宿題をやりなさい。","en":"Do your homework.","romaji":"Shukudai wo yarinasai."}],"example":"部屋を掃除しなさい。","exampleMeaning":"Clean your room."},{"pattern":"Verb にくい (〜nikui)","meaning":"Express difficulty or complexity; 'hard to', 'difficult to', 'not easily'.","formation":"Verb-stem + にくい","examples":[{"jp":"この字は読みにくいです。","en":"This character is hard to read.","romaji":"Kono ji wa yomi nikui desu."},{"jp":"このドアは開けにくい。","en":"This door is difficult to open.","romaji":"Kono doa wa ake nikui."},{"jp":"彼の字は読みにくい。","en":"His handwriting is hard to read.","romaji":"Kare no ji wa yomi nikui."},{"jp":"この料理は作りにくい。","en":"This dish is difficult to make.","romaji":"Kono ryouri wa tsukuri nikui."}],"example":"この字は読みにくいです。","exampleMeaning":"This character is hard to read."},{"pattern":"Verb やすい (〜yasui)","meaning":"Indicates that something is easy to do; 'easy to', 'easy for'.","formation":"Verb-stem + やすい","examples":[{"jp":"この本は読みやすいです。","en":"This book is easy to read.","romaji":"Kono hon wa yomiyasui desu."},{"jp":"このシャツは着やすい。","en":"This shirt is easy to wear.","romaji":"Kono shatsu wa kiyasui."},{"jp":"彼は話しやすい人です。","en":"He is an easy person to talk to.","romaji":"Kare wa hanashiyasui hito desu."},{"jp":"この料理は作りやすい。","en":"This dish is easy to make.","romaji":"Kono ryouri wa tsukuriyasui."}],"example":"この本は読みやすいです。","exampleMeaning":"This book is easy to read."},{"pattern":"Verb ようと思う (Verb-you to omou)","meaning":"Express intention or plan to do something; 'I think I will', 'I plan to', 'I intend to'.","formation":"Verb-volitional + と思う","examples":[{"jp":"明日、映画を見ようと思います。","en":"I think I will watch a movie tomorrow.","romaji":"Ashita, eiga o miyou to omoimasu."},{"jp":"週末に友達と遊ぼうと思っています。","en":"I plan to hang out with friends on the weekend.","romaji":"Shuumatsu ni tomodachi to asobou to omotteimasu."},{"jp":"勉強をもっと頑張ろうと思う。","en":"I intend to study harder.","romaji":"Benkyou o motto ganbarou to omou."},{"jp":"来年は海外旅行に行こうと思っている。","en":"I plan to go on an overseas trip next year.","romaji":"Rainen wa kaigai ryokou ni ikou to omotteiru."}],"example":"明日、映画を見ようと思います。","exampleMeaning":"I think I will watch a movie tomorrow."},{"pattern":"Verb ように (〜you ni)","meaning":"Used to express 'like', 'as if', 'in order to', or 'so that'.","formation":"Examples: Noun + のように / Verb-casual + ように / い-adjective + ように","examples":[{"jp":"彼女は鳥のように軽やかに踊る。","en":"She dances lightly like a bird.","romaji":"Kanojo wa tori no you ni karoyaka ni odoru."},{"jp":"覚えたことを忘れないように、毎日復習しましょう。","en":"In order not to forget what you've learned, let's review every day.","romaji":"Oboeta koto wo wasurenai you ni, mainichi fukushuu shimashou."},{"jp":"歌手になるように、毎日歌の練習をしています。","en":"In order to become a singer, I practice singing every day.","romaji":"Kashu ni naru you ni, mainichi uta no renshuu wo shiteimasu."},{"jp":"道を渡る時、車が来ないように確認してください。","en":"When crossing the road, please make sure no cars are coming.","romaji":"Michi wo wataru toki, kuruma ga konai you ni kakunin shite kudasai."}],"example":"彼女は鳥のように軽やかに踊る。","exampleMeaning":"She dances lightly like a bird."},{"pattern":"Verb ようにする","meaning":"Make an effort to; try to; see to it that; ensure that.","formation":"Verb-dictionary form + ようにする","examples":[{"jp":"毎日運動するようにしています。","en":"I try to exercise every day.","romaji":"Mainichi undou suru you ni shiteimasu."},{"jp":"早く寝るようにしてください。","en":"Please try to go to bed early.","romaji":"Hayaku neru you ni shite kudasai."},{"jp":"約束を守るようにします。","en":"I will make sure to keep my promise.","romaji":"Yakusoku o mamoru you ni shimasu."},{"jp":"彼に会わないようにする。","en":"I will try not to see him.","romaji":"Kare ni awanai you ni suru."}],"example":"毎日運動するようにしています。","exampleMeaning":"I try to exercise every day."},{"pattern":"Verb ようになる (〜you ni naru)","meaning":"Express a change in ability, situation or state; 'become able to', 'come to', 'begin to'.","formation":"Verb-dictionary/potential form + ようになる","examples":[{"jp":"日本語が話せるようになりました。","en":"I have become able to speak Japanese.","romaji":"Nihongo ga hanaseru you ni narimashita."},{"jp":"最近、早く寝るようになった。","en":"Recently, I have come to go to bed early.","romaji":"Saikin, hayaku neru you ni natta."},{"jp":"彼はピアノを弾けるようになりました。","en":"He has become able to play the piano.","romaji":"Kare wa piano wo hikeru you ni narimashita."},{"jp":"この仕事を始めてから、毎日忙しいと感じるようになりました。","en":"Since I started this job, I've begun to feel busy every day.","romaji":"Kono shigoto o hajimete kara, mainichi isogashii to kanjiru you ni narimashita."}],"example":"日本語が話せるようになりました。","exampleMeaning":"I have become able to speak Japanese."},{"pattern":"Verb ように言う (Verb-you ni iu)","meaning":"Tell someone to do something; 'tell to do', 'instruct to do'.","formation":"Verb-casual + ように言う","examples":[{"jp":"先生は私たちに宿題をやるように言いました。","en":"The teacher told us to do our homework.","romaji":"Sensei wa watashitachi ni shukudai o yaru you ni iimashita."},{"jp":"母は弟に部屋を片付けるように言いました。","en":"My mother told my younger brother to clean his room.","romaji":"Haha wa otouto ni heya wo katazukeru you ni iimashita."},{"jp":"上司は私に報告書を提出するように言いました。","en":"My boss told me to submit the report.","romaji":"Joushi wa watashi ni houkokusho wo teishutsu suru you ni iimashita."},{"jp":"友達が私に早く来るように言いました。","en":"My friend told me to come early.","romaji":"Tomodachi ga watashi ni hayaku kuru you ni iimashita."}],"example":"先生は私たちに宿題をやるように言いました。","exampleMeaning":"The teacher told us to do our homework."},{"pattern":"Verb られる (〜rareru)","meaning":"Expresses passive voice or potential form for verbs.","formation":"う-verb (passive): Replace the final う with われる / る-verb (passive & potential): Replace る with られる / Irregular: する → される, くる → こられる","examples":[{"jp":"彼は先生に褒められました。","en":"He was praised by the teacher.","romaji":"Kare wa sensei ni homeraremashita."},{"jp":"彼は友達に笑われました。","en":"He was laughed at by his friends.","romaji":"Kare wa tomodachi ni warawaremashita."},{"jp":"映画は観られましたか？","en":"Were you able to watch the movie?","romaji":"Eiga wa miraremashita ka?"},{"jp":"彼女はリーダーに選ばれました。","en":"She was chosen as the leader.","romaji":"Kanojo wa riidaa ni erabaremashita."}],"example":"彼は先生に褒められました。","exampleMeaning":"He was praised by the teacher."},{"pattern":"Verb る ことがある (〜ru koto ga aru)","meaning":"Used to express that something happens sometimes or has happened before.","formation":"Verb-dictionary form + ことがある","examples":[{"jp":"彼は遅刻することがあります。","en":"He is sometimes late.","romaji":"Kare wa chikoku suru koto ga arimasu."},{"jp":"私は寝坊することがあります。","en":"I sometimes oversleep.","romaji":"Watashi wa nebou suru koto ga arimasu."},{"jp":"彼女は歌を歌うことがあります。","en":"She sometimes sings songs.","romaji":"Kanojo wa uta o utau koto ga arimasu."},{"jp":"子供の頃、よく山に登ることがありました。","en":"When I was a child, I sometimes climbed mountains.","romaji":"Kodomo no koro, yoku yama ni noboru koto ga arimashita."}],"example":"彼は遅刻することがあります。","exampleMeaning":"He is sometimes late."},{"pattern":"Verb ることができる (〜ru koto ga dekiru)","meaning":"Express ability or possibility of doing an action; 'can', 'be able to', 'is possible'.","formation":"Verb-る + ことができる","examples":[{"jp":"私は日本語を話すことができます。","en":"I can speak Japanese.","romaji":"Watashi wa nihongo wo hanasu koto ga dekimasu."},{"jp":"彼はギターを弾くことができます。","en":"He can play the guitar.","romaji":"Kare wa gitaa wo hiku koto ga dekimasu."},{"jp":"この問題を解決することができますか？","en":"Can you solve this problem?","romaji":"Kono mondai wo kaiketsu suru koto ga dekimasu ka?"},{"jp":"彼女は犬を泳がせることができます。","en":"She can make the dog swim.","romaji":"Kanojo wa inu wo oyogaseru koto ga dekimasu."}],"example":"私は日本語を話すことができます。","exampleMeaning":"I can speak Japanese."},{"pattern":"Verb ることにする (〜ru koto ni suru)","meaning":"Decide to do something, make a decision.","formation":"Verb-る + ことにする","examples":[{"jp":"来週、ジムに行くことにしました。","en":"I decided to go to the gym next week.","romaji":"Raishuu, jimu ni iku koto ni shimashita."},{"jp":"この靴を買うことにしました。","en":"I decided to buy these shoes.","romaji":"Kono kutsu wo kau koto ni shimashita."},{"jp":"毎日、散歩をすることにしました。","en":"I decided to take a walk every day.","romaji":"Mainichi, sanpo wo suru koto ni shimashita."},{"jp":"彼に電話をかけることにします。","en":"I’ve decided to call him.","romaji":"Kare ni denwa wo kakeru koto ni shimasu."}],"example":"来週、ジムに行くことにしました。","exampleMeaning":"I decided to go to the gym next week."},{"pattern":"Verb る ことになる (〜ru koto ni naru)","meaning":"Indicates that something has been decided or arranged; 'it has been decided that', 'it turns out that'.","formation":"Verb-る + ことになる","examples":[{"jp":"今日は会議がなくなることになりました。","en":"It has been decided that there will be no meeting today.","romaji":"Kyou wa kaigi ga nakunaru koto ni narimashita."},{"jp":"来週、友達と旅行することになった。","en":"It has been arranged that I will travel with my friends next week.","romaji":"Raishuu, tomodachi to ryokou suru koto ni natta."},{"jp":"彼女が今度のプロジェクトのリーダーになることになりました。","en":"It has been decided that she will be the leader of the next project.","romaji":"Kanojo ga kondo no purojekuto no riida ni naru koto ni narimashita."},{"jp":"急に仕事が入ったので、休みを取ることになった。","en":"Due to sudden work, it has been decided that I will take a day off.","romaji":"Kyuu ni shigoto ga haitta node, yasumi wo toru koto ni natta."}],"example":"今日は会議がなくなることになりました。","exampleMeaning":"It has been decided that there will be no meeting today."},{"pattern":"Verb るときに (〜ru toki ni)","meaning":"Describes the time when a certain action takes place; 'when', 'at the time'.","formation":"Verb-る + ときに","examples":[{"jp":"映画を見るときに、ポップコーンを食べます。","en":"When I watch a movie, I eat popcorn.","romaji":"Eiga wo miru toki ni, poppukoon wo tabemasu."},{"jp":"寝るときに、部屋の電気を消します。","en":"When I go to bed, I turn off the room lights.","romaji":"Neru toki ni, heya no denki wo keshimasu."},{"jp":"運動するときに、水分補給が大切です。","en":"When exercising, it's important to stay hydrated.","romaji":"Undou suru toki ni, suibun hokyuu ga taisetsu desu."},{"jp":"旅行するときに、カメラを持っていくことが好きです。","en":"When I travel, I like to bring a camera.","romaji":"Ryokou suru toki ni, kamera wo motteiku koto ga suki desu."}],"example":"映画を見るときに、ポップコーンを食べます。","exampleMeaning":"When I watch a movie, I eat popcorn."},{"pattern":"Verb る ところ (Verb-ru tokoro)","meaning":"Expresses the state or moment when an action is about to happen or is happening.","formation":"Verb-dictionary form + ところ","examples":[{"jp":"彼は食べるところです。","en":"He is in the process of eating.","romaji":"Kare wa taberu tokoro desu."},{"jp":"私は出かけるところです。","en":"I am just about to leave.","romaji":"Watashi wa dekakeru tokoro desu."},{"jp":"彼女は泣くところでした。","en":"She was on the verge of crying.","romaji":"Kanojo wa naku tokoro deshita."},{"jp":"私たちは勉強するところです。","en":"We are in the middle of studying.","romaji":"Watashitachi wa benkyou suru tokoro desu."}],"example":"彼は食べるところです。","exampleMeaning":"He is in the process of eating."},{"pattern":"Verb 出す","meaning":"Express the action of taking something out, starting an action, or emphasizing a verb.","formation":"Verb stem + 出す (~dasu)","examples":[{"jp":"本を棚から出してください。","en":"Please take the book out from the shelf.","romaji":"Hon o tana kara dashite kudasai."},{"jp":"彼は部屋から急いで出ました。","en":"He rushed out of the room.","romaji":"Kare wa heya kara isoide demashita."},{"jp":"授業が始まる前に宿題を出してください。","en":"Submit your homework before class starts.","romaji":"Jugyou ga hajimaru mae ni shukudai wo dashite kudasai."},{"jp":"彼女は歌い出しました。","en":"She began to sing.","romaji":"Kanojo wa utaidashimashita."}],"example":"本を棚から出してください。","exampleMeaning":"Please take the book out from the shelf."},{"pattern":"Verb 方 (〜hou)","meaning":"Indicates the way or method of doing something; often read as '～かた' ('how to', 'the way of').","formation":"Verb-stem + 方 (read as かた)","examples":[{"jp":"誰かがケーキの作り方を知っていますか？","en":"Does anyone know how to make a cake?","romaji":"Dareka ga keeki no tsukurikata o shitteimasu ka?"},{"jp":"彼女は英語の話し方を学んでいます。","en":"She is learning how to speak English.","romaji":"Kanojo wa eigo no hanashikata o manandeimasu."},{"jp":"このパソコンの使い方を教えてください。","en":"Please teach me how to use this computer.","romaji":"Kono pasokon no tsukaikata o oshiete kudasai."},{"jp":"数学の問題の解き方を覚えるのが難しいです。","en":"It is difficult to remember the way to solve math problems.","romaji":"Suugaku no mondai no tokikata o oboeru no ga muzukashii desu."}],"example":"誰かがケーキの作り方を知っていますか？","exampleMeaning":"Does anyone know how to make a cake?"},{"pattern":"Verb 終わる (〜owaru)","meaning":"Verbal action is completed; 'to finish', 'to end'.","formation":"終わる (owaru) is a godan (u-verb)","examples":[{"jp":"映画が終わったら、家に帰ります。","en":"When the movie finishes, I'll go home.","romaji":"Eiga ga owattara, ie ni kaerimasu."},{"jp":"仕事が終わるまで、待ってください。","en":"Please wait until the work is finished.","romaji":"Shigoto ga owaru made, matte kudasai."},{"jp":"パーティーはもうすぐ終わります。","en":"The party will be over soon.","romaji":"Paatii wa mou sugu owarimasu."},{"jp":"試験が終わったら、友達と遊びに行く予定です。","en":"Once the exam is over, I plan to go out with my friends.","romaji":"Shiken ga owattara, tomodachi to asobi ni iku yotei desu."}],"example":"映画が終わったら、家に帰ります。","exampleMeaning":"When the movie finishes, I'll go home."},{"pattern":"Verb + 続ける (つづける, tsuzukeru)","meaning":"To continue doing or to keep doing an action.","formation":"Verb-masu-stem + 続ける","examples":[{"jp":"彼は毎日ジムで運動を続けています。","en":"He continues to exercise at the gym every day.","romaji":"Kare wa mainichi jimu de undou o tsuzuketeimasu."},{"jp":"彼女は勉強を続けるために図書館に行きました。","en":"She went to the library to continue studying.","romaji":"Kanojo wa benkyou o tsuzukeru tame ni toshokan ni ikimashita."},{"jp":"私たちは雨にも関わらず散歩を続けました。","en":"We continued walking despite the rain.","romaji":"Watashitachi wa ame ni mo kakawarazu sanpo o tsuzukemashita."},{"jp":"彼は仕事を続けることに決めた。","en":"He decided to continue working.","romaji":"Kare wa shigoto o tsuzukeru koto ni kimeta."}],"example":"彼は毎日ジムで運動を続けています。","exampleMeaning":"He continues to exercise at the gym every day."},{"pattern":"～かしら (〜kashira)","meaning":"Indicates uncertainty or doubt; 'I wonder', 'I'm not sure'.","formation":"Verb-casual + かしら, い-Adjective + かしら, な-Adjective + かしら, Noun + かしら","examples":[{"jp":"今日は雨が降るかしら？","en":"I wonder if it will rain today?","romaji":"Kyou wa ame ga furu kashira?"},{"jp":"このケーキは美味しいかしら？","en":"I wonder if this cake is delicious?","romaji":"Kono keeki wa oishii kashira?"},{"jp":"彼は病気かしら？","en":"I wonder if he is sick?","romaji":"Kare wa byouki kashira?"},{"jp":"彼女は学生かしら？","en":"I wonder if she is a student?","romaji":"Kanojo wa gakusei kashira?"}],"example":"今日は雨が降るかしら？","exampleMeaning":"I wonder if it will rain today?"},{"pattern":"～かどうか (〜ka dou ka)","meaning":"Used to express 'whether' or 'if' in indirect questions or statements.","formation":"Verb-casual + かどうか, い-Adjective + かどうか, な-Adjective + (だ)かどうか, Noun + (だ)かどうか","examples":[{"jp":"彼が来るかどうか知りません。","en":"I don't know if he will come or not.","romaji":"Kare ga kuru ka dou ka shirimasen."},{"jp":"この本が面白いかどうか教えてください。","en":"Please tell me if this book is interesting or not.","romaji":"Kono hon ga omoshiroi ka dou ka oshiete kudasai."},{"jp":"彼女が綺麗だかどうかは分かりません。","en":"I don't know whether she is beautiful or not.","romaji":"Kanojo ga kirei da ka dou ka wa wakarimasen."},{"jp":"彼が先生だかどうか覚えていません。","en":"I don't remember if he is a teacher or not.","romaji":"Kare ga sensei da ka dou ka oboete imasen."}],"example":"彼が来るかどうか知りません。","exampleMeaning":"I don't know if he will come or not."},{"pattern":"～かなあ (〜kanaa)","meaning":"Expresses uncertainty or wonder; 'I wonder', 'I'm not sure'.","formation":"Verb-casual + かなあ, い-Adjective + かなあ, (な-Adjective/Noun) + (だ) + かなあ","examples":[{"jp":"明日雨が降るかなあ。","en":"I wonder if it will rain tomorrow.","romaji":"Ashita ame ga furu kanaa."},{"jp":"このケーキは美味しいかなあ。","en":"I wonder if this cake is delicious.","romaji":"Kono keeki wa oishii kanaa."},{"jp":"彼は病気かなあ。","en":"I wonder if he is sick.","romaji":"Kare wa byouki kanaa."},{"jp":"彼女は学生かなあ。","en":"I wonder if she is a student.","romaji":"Kanojo wa gakusei kanaa."}],"example":"明日雨が降るかなあ。","exampleMeaning":"I wonder if it will rain tomorrow."},{"pattern":"～かもしれない (〜kamoshirenai)","meaning":"Express uncertainty; 'maybe', 'might', 'possibly'.","formation":"Verb-casual + かもしれない, い-Adjective + かもしれない, な-Adjective + だかもしれない, Noun + だかもしれない","examples":[{"jp":"明日雨が降るかもしれない。","en":"It might rain tomorrow.","romaji":"Ashita ame ga furu kamoshirenai."},{"jp":"このケーキは美味しいかもしれない。","en":"This cake might be delicious.","romaji":"Kono keeki wa oishii kamoshirenai."},{"jp":"彼が病気かもしれない。","en":"He might be sick.","romaji":"Kare ga byouki kamoshirenai."},{"jp":"彼女は学生かもしれない。","en":"She might be a student.","romaji":"Kanojo wa gakusei kamoshirenai."}],"example":"明日雨が降るかもしれない。","exampleMeaning":"It might rain tomorrow."},{"pattern":"～から (〜kara)","meaning":"Express a reason or cause; 'because', 'since', 'due to'.","formation":"Verb-casual + から, い-Adjective + から, な-Adjective + だから, Noun + だから","examples":[{"jp":"雨が降るから、傘を持って行ってください。","en":"Because it's raining, please bring an umbrella.","romaji":"Ame ga furu kara, kasa wo motte itte kudasai."},{"jp":"このケーキは美味しいから、みんな食べるでしょう。","en":"Because this cake is delicious, everyone will probably eat it.","romaji":"Kono keeki wa oishii kara, minna taberu deshou."},{"jp":"彼は病気だから、学校を休みます。","en":"He will be absent from school because he is sick.","romaji":"Kare wa byouki dakara, gakkou wo yasumimasu."},{"jp":"今日は日曜日だから、学校がありません。","en":"There is no school today because it is Sunday.","romaji":"Kyou wa nichiyoubi dakara, gakkou ga arimasen."}],"example":"雨が降るから、傘を持って行ってください。","exampleMeaning":"Because it's raining, please bring an umbrella."},{"pattern":"～けれど (〜keredo)","meaning":"Indicate a soft contrast or contradiction; 'but', 'however'.","formation":"Verb-casual + けれど, い-Adjective + けれど, な-Adjective + だけれど, Noun + だけれど","examples":[{"jp":"今日は忙しいけれど、明日はもっと時間がある。","en":"I'm busy today, but I have more time tomorrow.","romaji":"Kyou wa isogashii keredo, ashita wa motto jikan ga aru."},{"jp":"このレストランは高いけれど、料理が美味しい。","en":"This restaurant is expensive, but the food is delicious.","romaji":"Kono resutoran wa takai keredo, ryouri ga oishii."},{"jp":"彼は若いけれど、とても経験豊富だ。","en":"He is young, but he is very experienced.","romaji":"Kare wa wakai keredo, totemo keiken houfu da."},{"jp":"彼女は病気だけれど、明るく元気だ。","en":"She is sick, but she is cheerful and energetic.","romaji":"Kanojo wa byouki da keredo, akaruku genki da."}],"example":"今日は忙しいけれど、明日はもっと時間がある。","exampleMeaning":"I'm busy today, but I have more time tomorrow."},{"pattern":"～させてください (〜sasete kudasai)","meaning":"Express a polite request to allow or permit someone to do something.","formation":"Verb-causative form + ください","examples":[{"jp":"もう少し考えさせてください。","en":"Please let me think a little more.","romaji":"Mou sukoshi kangaesasete kudasai."},{"jp":"写真を撮らせてください。","en":"Please let me take a photo.","romaji":"Shashin o torasete kudasai."},{"jp":"もうちょっと練習させてください。","en":"Please let me practice a little more.","romaji":"Mou chotto renshuu sasete kudasai."},{"jp":"ここで待たせてください。","en":"Please let me wait here.","romaji":"Koko de matasete kudasai."}],"example":"もう少し考えさせてください。","exampleMeaning":"Please let me think a little more."},{"pattern":"～し、～し、～ (〜shi, 〜shi, 〜)","meaning":"Express multiple reasons or characteristics; 'and', 'because', 'since'.","formation":"Verb-casual + し, い-Adjective + し, な-Adjective + だし, Noun + だし","examples":[{"jp":"彼は若いし、元気だし、フレンドリーだし、みんなと仲良くなれると思います。","en":"He is young, energetic, friendly, and I think he can get along with everyone.","romaji":"Kare wa wakai shi, genki da shi, furendorī da shi, minna to nakayoku nareru to omoimasu."},{"jp":"このレストランは料理が美味しいし、雰囲気がいいし、価格も手頃だからお勧めです。","en":"I recommend this restaurant because the food is delicious, the atmosphere is nice, and the prices are reasonable.","romaji":"Kono resutoran wa ryouri ga oishii shi, fun'iki ga ii shi, kakaku mo tegoro dakara osusume desu."},{"jp":"彼女は勉強ができるし、スポーツも得意だし、性格もいい。","en":"She is good at studying, good at sports, and has a good personality.","romaji":"Kanojo wa benkyou ga dekiru shi, supōtsu mo tokui da shi, seikaku mo ii."},{"jp":"今日は寒いし、雨も降っているし、家でゆっくり休んだ方がいいでしょう。","en":"It's cold today, and it's raining, so it's better to relax at home.","romaji":"Kyou wa samui shi, ame mo futte iru shi, ie de yukkuri yasunda hou ga ii deshou."}],"example":"彼は若いし、元気だし、フレンドリーだし、みんなと仲良くなれると思います。","exampleMeaning":"He is young, energetic, friendly, and I think he can get along with everyone."},{"pattern":"～すぎる (〜sugiru)","meaning":"Expresses that something is excessive or overdone; 'too much', 'too', 'over'.","formation":"Verb-stem + すぎる, い-Adjective (remove い) + すぎる, な-Adjective + すぎる","examples":[{"jp":"この部屋は暑すぎる。","en":"This room is too hot.","romaji":"Kono heya wa atsui sugiru."},{"jp":"彼は早く来すぎた。","en":"He came too early.","romaji":"Kare wa hayaku kisugita."},{"jp":"この箱は重すぎて持ち上げられない。","en":"This box is too heavy to lift.","romaji":"Kono hako wa omosugite mochiagerarenai."},{"jp":"彼女は忙しくて遊びすぎはしない。","en":"She's too busy to play too much.","romaji":"Kanojo wa isogashikute asobisugi wa shinai."}],"example":"この部屋は暑すぎる。","exampleMeaning":"This room is too hot."},{"pattern":"～ずつ (〜zutsu)","meaning":"Indicates equal distribution; 'each', 'per', 'apiece'.","formation":"Noun + ずつ","examples":[{"jp":"りんごを2つずつ配ります。","en":"I will distribute 2 apples each.","romaji":"Ringo wo futatsu zutsu kubarimasu."},{"jp":"私たちは週に一度ずつ掃除をします。","en":"We each clean once per week.","romaji":"Watashitachi wa shuu ni ichido zutsu souji o shimasu."},{"jp":"みんなは同じ距離を一歩ずつ歩いた。","en":"Everyone walked the same distance, one step at a time.","romaji":"Minna wa onaji kyori o ippo zutsu aruita."},{"jp":"彼女は子供たちに一枚ずつプレゼントをくれました。","en":"She gave one present to each child.","romaji":"Kanojo wa kodomotachi ni ichimai zutsu purezento o kuremashita."}],"example":"りんごを2つずつ配ります。","exampleMeaning":"I will distribute 2 apples each."},{"pattern":"～そうだ (〜sou da)","meaning":"Express the appearance, seeming, or feeling of something; 'looks like', 'seems', 'appears'.","formation":"Verb-ますstem + そうだ, い-Adjective (without い) + そうだ, な-Adjective + そうだ","examples":[{"jp":"その花はとてもきれいそうだ。","en":"That flower looks very beautiful.","romaji":"Sono hana wa totemo kirei sou da."},{"jp":"彼は疲れそうだ。","en":"He looks tired.","romaji":"Kare wa tsukare sou da."},{"jp":"この本は面白そうだ。","en":"This book looks interesting.","romaji":"Kono hon wa omoshiro sou da."},{"jp":"雨が降りそうだ。","en":"It looks like it's going to rain.","romaji":"Ame ga furi sou da."}],"example":"その花はとてもきれいそうだ。","exampleMeaning":"That flower looks very beautiful."},{"pattern":"そんな (sonna) + Noun","meaning":"Expresses 'that kind/type of'; referring to something near the listener or previously mentioned.","formation":"そんな + Noun","examples":[{"jp":"そんな話、信じられない。","en":"I can't believe that kind of story.","romaji":"Sonna hanashi, shinjirarenai."},{"jp":"そんな映画、見たくない。","en":"I don't want to watch that kind of movie.","romaji":"Sonna eiga, mitakunai."}],"example":"そんな話、信じられない。","exampleMeaning":"I can't believe that kind of story."},{"pattern":"そんなに～ (sonna ni〜)","meaning":"Expresses 'not so much', 'not that', or 'not so ~'.","formation":"そんなに + Verb-negation, そんなに + Adjective-negation","examples":[{"jp":"そんなに急がなくてもいいですよ。","en":"You don't have to hurry that much.","romaji":"Sonna ni isoganakutemo ii desu yo."},{"jp":"そんなに難しくない問題だと思います。","en":"I don't think the problem is that difficult.","romaji":"Sonna ni muzukashikunai mondai da to omoimasu."},{"jp":"彼女はそんなに背が高くありません。","en":"She is not that tall.","romaji":"Kanojo wa sonna ni se ga takaku arimasen."},{"jp":"そんなにたくさん食べる必要はないと思う。","en":"I don't think there's a need to eat so much.","romaji":"Sonna ni takusan taberu hitsuyou wa nai to omou."}],"example":"そんなに急がなくてもいいですよ。","exampleMeaning":"You don't have to hurry that much."},{"pattern":"～たらいい (〜tara ii)","meaning":"Expressing a desire or suggestion for a particular outcome; 'it would be good if', 'should', 'I hope'.","formation":"Verb-casual-past + たらいい","examples":[{"jp":"もっと勉強したらいいですよ。","en":"It would be good if you studied more.","romaji":"Motto benkyou shitara ii desu yo."},{"jp":"雨が止んだらいいな。","en":"I hope the rain stops.","romaji":"Ame ga yandara ii na."},{"jp":"早く元気になったらいいですね。","en":"It would be good if you got well soon.","romaji":"Hayaku genki ni nattara ii desu ne."},{"jp":"彼に連絡したらいいと思います。","en":"I think it would be good if you contacted him.","romaji":"Kare ni renraku shitara ii to omoimasu."}],"example":"もっと勉強したらいいですよ。","exampleMeaning":"It would be good if you studied more."},{"pattern":"～たら いかがですか (〜tara ikaga desu ka)","meaning":"Making polite suggestions; 'how about if', 'what if', 'it would be good if'.","formation":"Verb-casual, past + たら いかがですか, い-Adjective + かったら いかがですか, な-Adjective + だったら いかがですか, Noun + だったら いかがですか","examples":[{"jp":"図書館に行ったらいかがですか。","en":"How about going to the library?","romaji":"Toshokan ni ittara ikaga desu ka."},{"jp":"寒かったらカーディガンを着るのはいかがですか。","en":"How about wearing a cardigan if it's cold?","romaji":"Samukattara kaadigan wo kiru no wa ikaga desu ka."},{"jp":"部屋が暗かったら照明を付けるのはいかがですか。","en":"What if you turn on the light if the room is dark?","romaji":"Heya ga kurakattara shoumei wo tsukeru no wa ikaga desu ka."},{"jp":"自分の意見だったら他人に聞くのはいかがですか。","en":"How about asking others if it's your own opinion?","romaji":"Jibun no iken dattara tanin ni kiku no wa ikaga desu ka."}],"example":"図書館に行ったらいかがですか。","exampleMeaning":"How about going to the library?"},{"pattern":"～たら どうですか (〜tara doudesuka)","meaning":"Express a suggestion or advice; 'what if', 'how about', 'why don't you'.","formation":"Verb-た form + ら どうですか","examples":[{"jp":"スキーに行ったらどうですか？","en":"How about going skiing?","romaji":"Sukii ni ittara doudesuka?"},{"jp":"少し休んだらどうですか？","en":"What if you take a little break?","romaji":"Sukoshi yasundara doudesuka?"},{"jp":"この本を読んだらどうですか？","en":"Why don't you read this book?","romaji":"Kono hon wo yondara doudesuka?"},{"jp":"タクシーで帰ったらどうですか？","en":"How about going home by taxi?","romaji":"Takushii de kaettara doudesuka?"}],"example":"スキーに行ったらどうですか？","exampleMeaning":"How about going skiing?"},{"pattern":"～たり～たり (〜tari 〜tari)","meaning":"Used to list multiple actions or states; 'doing things like', 'and so on', 'etc.'","formation":"Verb-ta + り + next verb-ta + り, い-Adjective + かったり + next verb-ta + り, な-Adjective + だったり + next verb-ta + り, Noun + だったり + next verb-ta + り","examples":[{"jp":"週末は映画を観たり、本を読んだりする。","en":"On weekends, I do things like watching movies and reading books.","romaji":"Shuumatsu wa eiga wo mitari, hon wo yondari suru."},{"jp":"彼女は料理が上手だったり、歌がうまかったりする。","en":"She is good at things like cooking and singing.","romaji":"Kanojo wa ryouri ga jouzu dattari, uta ga umakattari suru."},{"jp":"このリゾートではスキーをしたり、温泉に入ったりできる。","en":"At this resort, you can do things like skiing and going to hot springs.","romaji":"Kono rizooto de wa sukii wo shitari, onsen ni haittari dekiru."},{"jp":"この地域の天気は暑かったり、寒かったりする。","en":"The weather in this area can be hot or cold.","romaji":"Kono chiiki no tenki wa atsukattari, samukattari suru."}],"example":"週末は映画を観たり、本を読んだりする。","exampleMeaning":"On weekends, I do things like watching movies and reading books."},{"pattern":"～だろう (〜darou)","meaning":"Express probability, likelihood or certainty; 'probably', 'maybe', 'I think'.","formation":"Verb-casual + だろう, い-Adjective (drop い) + だろう, な-Adjective + だろう, Noun + だろう","examples":[{"jp":"明日は晴れるだろう。","en":"It will probably be sunny tomorrow.","romaji":"Ashita wa hareru darou."},{"jp":"彼は忙しいだろう。","en":"He is probably busy.","romaji":"Kare wa isogashii darou."},{"jp":"この本は面白いだろう。","en":"This book is probably interesting.","romaji":"Kono hon wa omoshiroi darou."},{"jp":"彼女は先生だろう。","en":"She is probably a teacher.","romaji":"Kanojo wa sensei darou."}],"example":"明日は晴れるだろう。","exampleMeaning":"It will probably be sunny tomorrow."},{"pattern":"～っていう (〜tte iu)","meaning":"Used to quote, define, or specify a noun.","formation":"Noun/Adjective/Verb + っていう + Noun","examples":[{"jp":"ピザっていう料理が大好きです。","en":"I love the dish called pizza.","romaji":"Piza tte iu ryouri ga daisuki desu."},{"jp":"彼っていう男性はすごく面白いです。","en":"That man (called ‘kare’) is really interesting.","romaji":"Kare tte iu dansei wa sugoku omoshiroi desu."},{"jp":"この映画っていうのは本当に感動的だよ。","en":"This movie, I mean, is really touching.","romaji":"Kono eiga tte iu no wa hontou ni kandouteki da yo."},{"jp":"彼女が言っているっていう店はここではない。","en":"The store she's talking about, I mean, is not here.","romaji":"Kanojo ga itte iru tte iu mise wa koko de wa nai."}],"example":"ピザっていう料理が大好きです。","exampleMeaning":"I love the dish called pizza."},{"pattern":"～で (〜de)","meaning":"Indicates the means, method, or place.","formation":"Noun + ～で","examples":[{"jp":"私は自転車で学校に行きます。","en":"I go to school by bicycle.","romaji":"Watashi wa jitensha de gakkou ni ikimasu."},{"jp":"彼は日本語で手紙を書いた。","en":"He wrote a letter in Japanese.","romaji":"Kare wa nihongo de tegami wo kaita."},{"jp":"鉛筆で絵を描きました。","en":"I drew a picture with a pencil.","romaji":"Enpitsu de e wo kakimashita."},{"jp":"レストランで昼食を食べました。","en":"I had lunch at a restaurant.","romaji":"Resutoran de chuushoku wo tabemashita."}],"example":"私は自転車で学校に行きます。","exampleMeaning":"I go to school by bicycle."},{"pattern":"～でしょう (〜deshou)","meaning":"A conjecture or probability; 'probably', 'I think', 'it seems'.","formation":"Verb-ますstem + でしょう, い-Adjective + でしょう, な-Adjective + でしょう, Noun + でしょう","examples":[{"jp":"明日は晴れでしょう。","en":"It will probably be sunny tomorrow.","romaji":"Ashita wa hare deshou."},{"jp":"彼は元気でしょう。","en":"He is probably fine.","romaji":"Kare wa genki deshou."},{"jp":"この本は面白いでしょう。","en":"This book is probably interesting.","romaji":"Kono hon wa omoshiroi deshou."},{"jp":"彼女は医者でしょう。","en":"She is probably a doctor.","romaji":"Kanojo wa isha deshou."}],"example":"明日は晴れでしょう。","exampleMeaning":"It will probably be sunny tomorrow."},{"pattern":"～てはいけない (〜te wa ikenai)","meaning":"Expresses prohibition; 'must not', 'cannot'.","formation":"Verb-て-form + はいけない","examples":[{"jp":"公園でたばこを吸ってはいけない。","en":"You must not smoke in the park.","romaji":"Kouen de tabako o sutte wa ikenai."},{"jp":"ここで写真を撮ってはいけない。","en":"You cannot take pictures here.","romaji":"Koko de shashin o totte wa ikenai."},{"jp":"図書館で大きな声を出してはいけない。","en":"You must not speak loudly in the library.","romaji":"Toshokan de ookina koe o dashite wa ikenai."},{"jp":"バスの中で立っている人に席を譲ってはいけない。(Note: Unusual in real life, but grammatically correct.)","en":"You should not give up your seat to someone standing on the bus. (Note: Odd in actual social context, but valid grammar.)","romaji":"Basu no naka de tatteiru hito ni seki o yuzutte wa ikenai."}],"example":"公園でたばこを吸ってはいけない。","exampleMeaning":"You must not smoke in the park."},{"pattern":"～てもいい (〜temo ii)","meaning":"To give or ask permission; 'it's okay to', 'may', 'can'.","formation":"Verb-て form + もいい","examples":[{"jp":"ここで写真を撮ってもいいですか。","en":"Is it okay to take a photo here?","romaji":"Koko de shashin wo tottemo ii desu ka?"},{"jp":"このリンゴを食べてもいいですか。","en":"May I eat this apple?","romaji":"Kono ringo wo tabetemo ii desu ka."},{"jp":"試験が終わったら、帰ってもいいです。","en":"You can go home after the exam is over.","romaji":"Shiken ga owattara, kaettemo ii desu."},{"jp":"今夜友達と遊んでもいい。","en":"It's okay to play with friends tonight.","romaji":"Kon'ya tomodachi to asondemo ii."}],"example":"ここで写真を撮ってもいいですか。","exampleMeaning":"Is it okay to take a photo here?"},{"pattern":"～ても/でも (〜te mo/demo)","meaning":"Expresses 'even if' or 'even though'; used to convey contradiction or contrast.","formation":"Verb-て-form + も, い-Adjective (-い) + くても, な-Adjective + でも, Noun + でも","examples":[{"jp":"雨が降っても、学校に行きます。","en":"Even if it rains, I will go to school.","romaji":"Ame ga futte mo, gakkou ni ikimasu."},{"jp":"この部屋が汚くても、掃除しないつもりです。","en":"Even if this room is dirty, I don't intend to clean it.","romaji":"Kono heya ga kitanakute mo, souji shinai tsumori desu."},{"jp":"その映画が面白くなくても、見ます。","en":"Even if that movie is not interesting, I will watch it.","romaji":"Sono eiga ga omoshirokunakute mo, mimasu."},{"jp":"彼女が病気でも、働きます。","en":"Even if she is sick, she will work.","romaji":"Kanojo ga byouki demo, hatarakimasu."}],"example":"雨が降っても、学校に行きます。","exampleMeaning":"Even if it rains, I will go to school."},{"pattern":"～といい (〜to ii)","meaning":"Express a wish or hope; 'I hope', 'it would be good if'.","formation":"Verb-casual + といい, い-Adjective + といい, な-Adjective + だといい, Noun + だといい","examples":[{"jp":"明日晴れるといいね。","en":"I hope it will be sunny tomorrow.","romaji":"Ashita hareru to ii ne."},{"jp":"この試験に合格するといい。","en":"I hope to pass this exam.","romaji":"Kono shiken ni goukaku suru to ii."},{"jp":"彼が元気だといいな。","en":"I hope he is doing well.","romaji":"Kare ga genki da to ii na."},{"jp":"そのレストランが美味しいといいですね。","en":"It would be nice if that restaurant is delicious.","romaji":"Sono resutoran ga oishii to ii desu ne."}],"example":"明日晴れるといいね。","exampleMeaning":"I hope it will be sunny tomorrow."},{"pattern":"～という (〜to iu) Noun","meaning":"Used to define or explain a noun more specifically.","formation":"Noun + という + Noun, な-Adjective + という + Noun, Adjectival Verb + という + Noun","examples":[{"jp":"彼は日本語が流暢なアメリカ人という人です。","en":"He is an American who speaks fluent Japanese.","romaji":"Kare wa nihongo ga ryuuchou na amerikajin to iu hito desu."},{"jp":"昨日、美味しかったというケーキを食べました。","en":"Yesterday, I ate a cake that was said to be delicious.","romaji":"Kinou, oishikatta to iu keeki wo tabemashita."},{"jp":"有名な歌手という彼女は、たくさんのファンがいます。","en":"She, who is called a famous singer, has many fans.","romaji":"Yuumei na kashu to iu kanojo wa, takusan no fan ga imasu."},{"jp":"環境に優しいという製品が人気があります。","en":"Products that are said to be environmentally friendly are popular.","romaji":"Kankyou ni yasashii to iu seihin ga ninki ga arimasu."}],"example":"彼は日本語が流暢なアメリカ人という人です。","exampleMeaning":"He is an American who speaks fluent Japanese."},{"pattern":"どういう Noun","meaning":"Asking for clarification or more information about a noun; 'what kind of', 'what sort of'.","formation":"どういう + Noun","examples":[{"jp":"どういう仕事をしていますか？","en":"What kind of work do you do?","romaji":"Dou iu shigoto wo shite imasu ka?"},{"jp":"どういう映画が好きですか？","en":"What kind of movies do you like?","romaji":"Dou iu eiga ga suki desu ka?"},{"jp":"どういう服を着たいですか？","en":"What kind of clothes do you want to wear?","romaji":"Dou iu fuku wo kitai desu ka?"},{"jp":"どういう理由で遅れましたか？","en":"What sort of reason caused you to be late?","romaji":"Dou iu riyuu de okuremashita ka?"}],"example":"どういう仕事をしていますか？","exampleMeaning":"What kind of work do you do?"},{"pattern":"～と思う (〜to omou)","meaning":"Express one's thoughts or opinions; 'I think', 'I believe'.","formation":"Verb-casual + と思う, い-Adjective + と思う, な-Adjective + だと思う, Noun + だと思う","examples":[{"jp":"明日晴れると思います。","en":"I think it will be sunny tomorrow.","romaji":"Ashita hareru to omoimasu."},{"jp":"この映画は面白いと思う。","en":"I think this movie is interesting.","romaji":"Kono eiga wa omoshiroi to omou."},{"jp":"彼は親切だと思います。","en":"I think he is kind.","romaji":"Kare wa shinsetsu da to omoimasu."},{"jp":"鈴木さんは先生だと思う。","en":"I think Suzuki-san is a teacher.","romaji":"Suzuki-san wa sensei da to omou."}],"example":"明日晴れると思います。","exampleMeaning":"I think it will be sunny tomorrow."},{"pattern":"～という (〜to iu)","meaning":"Used to quote, express hearsay or define something.","formation":"Verb-casual + という, い-Adjective + という, な-Adjective + という, Noun + という","examples":[{"jp":"彼は「好きだ」と言った。","en":"He said 'I like you'.","romaji":"Kare wa 'suki da' to itta."},{"jp":"その映画は面白いという評判があります。","en":"The movie has a reputation for being interesting.","romaji":"Sono eiga wa omoshiroi to iu hyouban ga arimasu."},{"jp":"日本には富士山という高い山があります。","en":"In Japan, there is a tall mountain called Mount Fuji.","romaji":"Nihon ni wa Fujisan to iu takai yama ga arimasu."},{"jp":"彼女は難しい仕事をしているという話です。","en":"I heard she is doing a difficult job.","romaji":"Kanojo wa muzukashii shigoto o shiteiru to iu hanashi desu."}],"example":"彼は「好きだ」と言った。","exampleMeaning":"He said 'I like you'."},{"pattern":"～ないといけない (〜nai to ikenai)","meaning":"Express a necessity; 'must', 'have to', 'need to'.","formation":"Verb-negative + といけない","examples":[{"jp":"明日試験があるから、今夜勉強しないといけない。","en":"I have an exam tomorrow, so I have to study tonight.","romaji":"Ashita shiken ga aru kara, kon'ya benkyou shinai to ikenai."},{"jp":"９時に出発しないといけない。","en":"We must leave at 9 o'clock.","romaji":"Ku-ji ni shuppatsu shinai to ikenai."},{"jp":"風邪をひかないように、手をよく洗わないといけない。","en":"To avoid catching a cold, we have to wash our hands well.","romaji":"Kaze o hikanai you ni, te o yoku arawanai to ikenai."},{"jp":"この仕事は明日までに終わらないといけない。","en":"This work must be finished by tomorrow.","romaji":"Kono shigoto wa ashita made ni owaranai to ikenai."}],"example":"明日試験があるから、今夜勉強しないといけない。","exampleMeaning":"I have an exam tomorrow, so I have to study tonight."},{"pattern":"～なきゃいけない (〜nakya ikenai)","meaning":"Express a necessity or obligation; 'must', 'have to'.","formation":"Verb-casual (negative form without い) + なきゃいけない","examples":[{"jp":"明日までに宿題を終わらなきゃいけない。","en":"I have to finish my homework by tomorrow.","romaji":"Ashita made ni shukudai wo owaranakya ikenai."},{"jp":"もうすぐ出かけるから、急いで準備しなきゃいけない。","en":"We're leaving soon, so I have to hurry and get ready.","romaji":"Mou sugu dekakeru kara, isoide junbi shinakya ikenai."},{"jp":"このプロジェクトは来週提出しなきゃいけない。","en":"I must submit this project by next week.","romaji":"Kono purojekuto wa raishuu teishutsu shinakya ikenai."},{"jp":"電車に乗る前に、切符を買わなきゃいけない。","en":"I have to buy a ticket before getting on the train.","romaji":"Densha ni noru mae ni, kippu wo kawanakya ikenai."}],"example":"明日までに宿題を終わらなきゃいけない。","exampleMeaning":"I have to finish my homework by tomorrow."},{"pattern":"～なくちゃいけない (〜naku cha ikenai)","meaning":"Express the obligation to do something; 'have to', 'must', 'need to'.","formation":"Verb-ない form (-ない ending is dropped) + なくちゃいけない","examples":[{"jp":"仕事に行かなくちゃいけないので、早起きしなければなりません。","en":"I have to go to work, so I must wake up early.","romaji":"Shigoto ni ikanakucha ikenai node, hayaoki shinakereba narimasen."},{"jp":"試験があるから、勉強しなくちゃいけません。","en":"I have a test, so I must study.","romaji":"Shiken ga aru kara, benkyou shinakucha ikemasen."},{"jp":"パスポートを更新しなくちゃいけないので、大使館に行かなければ。","en":"I have to renew my passport, so I need to go to the embassy.","romaji":"Pasupooto wo koushin shinakucha ikenai node, taishikan ni ikanakereba."},{"jp":"今日はお金を払わなくちゃいけないから、銀行に行かないと。","en":"I have to pay money today, so I need to go to the bank.","romaji":"Kyou wa okane wo harawanakucha ikenai kara, ginkou ni ikanaito."}],"example":"仕事に行かなくちゃいけないので、早起きしなければなりません。","exampleMeaning":"I have to go to work, so I must wake up early."},{"pattern":"～なくてはいけない (〜nakute wa ikenai)","meaning":"Expresses the necessity or obligation; 'must', 'have to'.","formation":"Verb-negative form + なくてはいけない","examples":[{"jp":"宿題をしなくてはいけない。","en":"I have to do my homework.","romaji":"Shukudai o shinakute wa ikenai."},{"jp":"この手紙を明日までに出さなくてはいけない。","en":"I must send this letter by tomorrow.","romaji":"Kono tegami o ashita made ni dasanakute wa ikenai."},{"jp":"食べ物を無駄にしなくてはいけない。","en":"We must not waste food.","romaji":"Tabemono o muda ni shinakute wa ikenai."},{"jp":"早退したいが、授業が終わるまで待たなくてはいけない。","en":"I want to leave early, but I have to wait until the class finishes.","romaji":"Soutai shitai ga, jugyou ga owaru made matanakute wa ikenai."}],"example":"宿題をしなくてはいけない。","exampleMeaning":"I have to do my homework."},{"pattern":"～なくてもいい (〜nakutemo ii)","meaning":"Expresses that something is not necessary to do; 'it's okay if not', 'don't have to'.","formation":"Verb-ない-form + てもいい","examples":[{"jp":"コーヒーは飲まなくてもいいです。","en":"You don't have to drink the coffee.","romaji":"Koohii wa nomanakutemo ii desu."},{"jp":"宿題を今日しなくてもいいです。","en":"It's okay if you don't do your homework today.","romaji":"Shukudai wo kyou shinakutemo ii desu."},{"jp":"すぐに返事をしなくてもいいですよ。","en":"You don't have to reply immediately.","romaji":"Sugu ni henji wo shinakutemo ii desu yo."},{"jp":"全部食べなくてもいいですから、無理しないでください。","en":"You don't have to eat everything, so please don't force yourself.","romaji":"Zenbu tabenakutemo ii desu kara, muri shinai de kudasai."}],"example":"コーヒーは飲まなくてもいいです。","exampleMeaning":"You don't have to drink the coffee."},{"pattern":"～なければ ならない (〜nakereba naranai)","meaning":"Express obligation or necessity; 'must', 'have to', 'need to'.","formation":"Verb-ない form + なければ ならない","examples":[{"jp":"宿題をやらなければならない。","en":"I have to do my homework.","romaji":"Shukudai wo yaranakereba naranai."},{"jp":"明日までにこの本を読まなければならない。","en":"I have to read this book by tomorrow.","romaji":"Ashita made ni kono hon wo yomanakereba naranai."},{"jp":"授業に遅れないように、早く起きなければならない。","en":"I have to wake up early so I don't be late for class.","romaji":"Jugyou ni okurenai you ni, hayaku okinakereba naranai."},{"jp":"旅行に行く前に切符を買わなければならない。","en":"I have to buy a ticket before going on a trip.","romaji":"Ryokou ni iku mae ni kippu wo kawanakereba naranai."}],"example":"宿題をやらなければならない。","exampleMeaning":"I have to do my homework."},{"pattern":"～に (〜ni)","meaning":"Indicates direction, destination, purpose, or time.","formation":"Noun + に","examples":[{"jp":"母は私にケーキを作りました。","en":"My mother made a cake for me.","romaji":"Haha wa watashi ni keiki wo tsukurimashita."},{"jp":"彼女は東京に引っ越しました。","en":"She moved to Tokyo.","romaji":"Kanojo wa Toukyou ni hikkoshimashita."},{"jp":"銀行にお金を預けます。","en":"I deposit money in the bank.","romaji":"Ginkou ni okane wo azukemasu."},{"jp":"私は７時に起きます。","en":"I wake up at 7 o'clock.","romaji":"Watashi wa shichi ji ni okimasu."}],"example":"母は私にケーキを作りました。","exampleMeaning":"My mother made a cake for me."},{"pattern":"～ので (〜node)","meaning":"Express a reason or a cause for something; 'because', 'since', 'so'.","formation":"Verb-casual + ので, い-Adjective + ので, な-Adjective + なので, Noun + なので","examples":[{"jp":"明日試験があるので、今晩勉強します。","en":"I will study tonight because there is a test tomorrow.","romaji":"Ashita shiken ga aru node, konban benkyou shimasu."},{"jp":"このドレスが高いので、買わないことにします。","en":"I will not buy this dress because it is expensive.","romaji":"Kono doresu ga takai node, kawanai koto ni shimasu."},{"jp":"田中さんは病気なので、今日は来ません。","en":"Tanaka-san will not come today since he is sick.","romaji":"Tanaka-san wa byouki na node, kyou wa kimasen."},{"jp":"雨が降っているので、外に出ない方がいいですよ。","en":"It is better not to go outside because it is raining.","romaji":"Ame ga futte iru node, soto ni denai hou ga ii desu yo."}],"example":"明日試験があるので、今晩勉強します。","exampleMeaning":"I will study tonight because there is a test tomorrow."},{"pattern":"～のです (〜no desu)","meaning":"Provides an explanation or gives background information; 'the fact is', 'the reason is', 'actually'.","formation":"Verb-casual + のです, い-Adjective + のです, な-Adjective + なのです, Noun + なのです","examples":[{"jp":"この本は難しいのです。","en":"This book is difficult, you see.","romaji":"Kono hon wa muzukashii no desu."},{"jp":"明日は忙しいのです。","en":"The fact is, I am busy tomorrow.","romaji":"Ashita wa isogashii no desu."},{"jp":"彼女は英語の先生なのです。","en":"The reason is, she is an English teacher.","romaji":"Kanojo wa eigo no sensei na no desu."},{"jp":"私は風邪なのです。","en":"Actually, I’ve got a cold.","romaji":"Watashi wa kaze na no desu."}],"example":"この本は難しいのです。","exampleMeaning":"This book is difficult, you see."},{"pattern":"～のに (〜no ni)","meaning":"Used to express contrast between expectation and reality, or to indicate a purpose for doing something","formation":"Verb-casual + のに, い-Adjective + のに, な-Adjective + なのに, Noun + なのに","examples":[{"jp":"遅刻したのに、先生は怒らなかった。","en":"Even though I was late, the teacher didn't get angry.","romaji":"Chikoku shita no ni, sensei wa okoranakatta."},{"jp":"彼は疲れているのに、まだ働いています。","en":"Despite being tired, he is still working.","romaji":"Kare wa tsukarete iru no ni, mada hataraite imasu."},{"jp":"勉強するのに静かな場所が必要です。","en":"In order to study, I need a quiet place.","romaji":"Benkyou suru no ni, shizukana basho ga hitsuyou desu."},{"jp":"健康のために毎日運動するのに、うちでヨガをしている。","en":"In order to exercise for my health every day, I do yoga at home.","romaji":"Kenkou no tame ni mainichi undou suru no ni, uchi de yoga wo shite iru."}],"example":"遅刻したのに、先生は怒らなかった。","exampleMeaning":"Even though I was late, the teacher didn't get angry."},{"pattern":"～ばいい (〜ba ii)","meaning":"Express a suggestion or advice; 'should', 'it would be good if'.","formation":"Verb-ば-form + いい, い-Adjective + ければいい, な-Adjective + であればいい, Noun + であればいい","examples":[{"jp":"もっと勉強すればいい。","en":"You should study more.","romaji":"Motto benkyou sureba ii."},{"jp":"お腹が空いたら、何か食べればいい。","en":"If you're hungry, you should eat something.","romaji":"Onaka ga suita ra, nanika tabereba ii."},{"jp":"もっと速く走ればいい。","en":"You should run faster.","romaji":"Motto hayaku hashireba ii."},{"jp":"わからなければ、先生に聞けばいい。","en":"If you don't understand, you should ask the teacher.","romaji":"Wakaranakereba, sensei ni kikeba ii."}],"example":"もっと勉強すればいい。","exampleMeaning":"You should study more."},{"pattern":"～まで (〜made)","meaning":"Indicates extent, 'until', 'up to', 'as far as', 'even'.","formation":"Verb + まで, い-Adjective + まで, な-Adjective + まで, Noun + まで","examples":[{"jp":"仕事が終わるまで待っています。","en":"I will wait until work is finished.","romaji":"Shigoto ga owaru made matteimasu."},{"jp":"ここから駅まで歩いて10分かかります。","en":"It takes 10 minutes to walk from here to the station.","romaji":"Koko kara eki made aruite juppun kakarimasu."},{"jp":"私は彼が成功するまで応援します。","en":"I will support him until he succeeds.","romaji":"Watashi wa kare ga seikou suru made ouen shimasu."},{"jp":"彼女は猫まで好きです。","en":"She likes even cats.","romaji":"Kanojo wa neko made suki desu."}],"example":"仕事が終わるまで待っています。","exampleMeaning":"I will wait until work is finished."},{"pattern":"～までに (〜made ni)","meaning":"Express 'by' or 'before' a certain time or action.","formation":"Verb-casual + までに, Noun + までに, Time expression + までに","examples":[{"jp":"明日の朝８時までに起きてください。","en":"Please wake up by 8 a.m. tomorrow.","romaji":"Ashita no asa hachiji made ni okite kudasai."},{"jp":"来週の金曜日までにレポートを提出してください。","en":"Please submit the report by next Friday.","romaji":"Raishuu no kinyoubi made ni repooto wo teishutsu shite kudasai."},{"jp":"彼が帰るまでに料理を終わらせたい。","en":"I want to finish cooking before he comes back.","romaji":"Kare ga kaeru made ni ryouri wo owarasetai."},{"jp":"３０分までに駅に着く必要があります。","en":"We need to arrive at the station by 30 minutes (from now).","romaji":"Sanjuppun made ni eki ni tsuku hitsuyou ga arimasu."}],"example":"明日の朝８時までに起きてください。","exampleMeaning":"Please wake up by 8 a.m. tomorrow."},{"pattern":"～まま (〜mama)","meaning":"Express 'as it is', 'while' or 'unchanged state'.","formation":"Verb-てform + いる+ まま, Adjective (い & な) + まま, Noun + のまま","examples":[{"jp":"ドアを開けたまま出かけてしまった。","en":"I accidentally left with the door open.","romaji":"Doa o aketa mama dekakete shimatta."},{"jp":"彼は目覚まし時計を止めたまま寝てしまった。","en":"He fell asleep with the alarm clock stopped.","romaji":"Kare wa mezamashi dokei o tometa mama nete shimatta."},{"jp":"その部屋はきれいなままにしておいてください。","en":"Please keep the room clean.","romaji":"Sono heya wa kirei na mama ni shite oite kudasai."},{"jp":"彼女は子供のままの心を持っている。","en":"She has the heart of a child.","romaji":"Kanojo wa kodomo no mama no kokoro o motte iru."}],"example":"ドアを開けたまま出かけてしまった。","exampleMeaning":"I accidentally left with the door open."},{"pattern":"～みたいだ (〜mitai da)","meaning":"Indicates similarity, resemblance or 'like'; 'it seems', 'appears', 'looks like'.","formation":"Verb-casual + みたいだ, い-Adjective + みたいだ, な-Adjective + みたいだ, Noun + みたいだ","examples":[{"jp":"彼女が病気のみたいだ。","en":"She seems to be sick.","romaji":"Kanojo ga byouki no mitai da."},{"jp":"このドレスは高いみたいだ。","en":"This dress seems to be expensive.","romaji":"Kono doresu wa takai mitai da."},{"jp":"あの人は有名人みたいだ。","en":"That person looks like a celebrity.","romaji":"Ano hito wa yuumeijin mitai da."},{"jp":"彼は今忙しいみたいだ。","en":"It seems he is busy right now.","romaji":"Kare wa ima isogashii mitai da."}],"example":"彼女が病気のみたいだ。","exampleMeaning":"She seems to be sick."},{"pattern":"～も (〜mo)","meaning":"Indicates 'also', 'too', or 'as well'.","formation":"Verb-casual + も, い-Adjective + も, な-Adjective + も, Noun + も","examples":[{"jp":"私もお寿司が好きです。","en":"I also like sushi.","romaji":"Watashi mo osushi ga suki desu."},{"jp":"彼女は英語も日本語も話せます。","en":"She can speak both English and Japanese.","romaji":"Kanojo wa eigo mo nihongo mo hanasemasu."},{"jp":"その映画は面白いし、彼も見たいと言っています。","en":"That movie is interesting, and he also said he wants to see it.","romaji":"Sono eiga wa omoshiroi shi, kare mo mitai to itteimasu."},{"jp":"今日は寒いです。明日も寒いでしょう。","en":"It is cold today. It will probably be cold tomorrow as well.","romaji":"Kyou wa samui desu. Ashita mo samui deshou."}],"example":"私もお寿司が好きです。","exampleMeaning":"I also like sushi."},{"pattern":"～ようだ (〜you da)","meaning":"Expresses appearance, similarity or inference; 'it seems', 'it looks like', 'it appears'.","formation":"Verb-て form + ようだ, い-Adjective (drop い) + ようだ, な-Adjective + のようだ, Noun + のようだ","examples":[{"jp":"彼は元気がないようだ。","en":"He seems to be lacking energy.","romaji":"Kare wa genki ga nai you da."},{"jp":"この料理は美味しいようだ。","en":"This dish seems to be delicious.","romaji":"Kono ryouri wa oishii you da."},{"jp":"彼女は有名人のようだ。","en":"She seems like a famous person.","romaji":"Kanojo wa yuumeijin no you da."},{"jp":"この部屋は図書館のようだ。","en":"This room looks like a library.","romaji":"Kono heya wa toshokan no you da."}],"example":"彼は元気がないようだ。","exampleMeaning":"He seems to be lacking energy."},{"pattern":"～んです (〜n desu)","meaning":"Provide an explanation or reason; 'it is that', 'the thing is', 'the reason is'.","formation":"Verb-casual + んです, い-Adjective + んです, な-Adjective + なんです, Noun + なんです","examples":[{"jp":"遅れたんですが、電車が遅れました。","en":"I was late because the train was delayed.","romaji":"Okuretan desuga, densha ga okuremashita."},{"jp":"疲れたんです。","en":"I'm tired (that's why).","romaji":"Tsukareta n desu."},{"jp":"彼は優しいんです。","en":"The thing is, he is kind.","romaji":"Kare wa yasashii n desu."},{"jp":"宿題が多いんです。","en":"The reason is I have a lot of homework.","romaji":"Shukudai ga ooi n desu."}],"example":"遅れたんですが、電車が遅れました。","exampleMeaning":"I was late because the train was delayed."},{"pattern":"文A。そのうえ 文B。","meaning":"Shows additional information; 'furthermore', 'besides', 'in addition'.","formation":"Sentence A + そのうえ + Sentence B + 。","examples":[{"jp":"このソフトウェアは使いやすい。そのうえ、価格も手ごろだ。","en":"This software is easy to use. Furthermore, the price is reasonable.","romaji":"Kono sofutouea wa tsukaiyasui. Sono ue, kakaku mo tegoro da."},{"jp":"彼女は美人だ。そのうえ、頭もいい。","en":"She is beautiful. In addition, she is smart.","romaji":"Kanojo wa bijin da. Sono ue, atama mo ii."},{"jp":"この映画は面白い。そのうえ、俳優たちの演技も素晴らしい。","en":"This movie is interesting. Besides, the actors' performances are also great.","romaji":"Kono eiga wa omoshiroi. Sono ue, haiyuutachi no engi mo subarashii."},{"jp":"東京はたくさんの観光スポットがある。そのうえ、美味しいレストランも多い。","en":"Tokyo has many sightseeing spots. In addition, there are many delicious restaurants.","romaji":"Toukyou wa takusan no kankou supotto ga aru. Sono ue, oishii resutoran mo oi."}],"example":"このソフトウェアは使いやすい。そのうえ、価格も手ごろだ。","exampleMeaning":"This software is easy to use. Furthermore, the price is reasonable."},{"pattern":"文A。それで 文B (Bun A. Sorede Bun B)","meaning":"Used to connect two sentences; 'So', 'That's why', 'Therefore'.","formation":"Sentence A。それで Sentence B。","examples":[{"jp":"今日は暑いです。それで、エアコンをつけました。","en":"It is hot today. So, I turned on the air conditioner.","romaji":"Kyou wa atsui desu. Sorede, eakon wo tsukemashita."},{"jp":"電車が遅れました。それで、仕事に遅れてしまいました。","en":"The train was delayed. That's why I was late for work.","romaji":"Densha ga okuremashita. Sorede, shigoto ni okurete shimaimashita."},{"jp":"彼は疲れている。それで、早く寝ることにした。","en":"He is tired. Therefore, he decided to go to bed early.","romaji":"Kare wa tsukarete iru. Sorede, hayaku neru koto ni shita."},{"jp":"試験に合格しました。それで、友達とお祝いパーティーを開きました。","en":"I passed the exam. So, I held a celebration party with friends.","romaji":"Shiken ni goukaku shimashita. Sorede, tomodachi to oiwai paatii wo hirakimashita."}],"example":"今日は暑いです。それで、エアコンをつけました。","exampleMeaning":"It is hot today. So, I turned on the air conditioner."},{"pattern":"文A。それに 文B (Bun A. Soreni Bun B)","meaning":"Express 'in addition to; besides,' used to include additional information.","formation":"Sentence A + それに + Sentence B","examples":[{"jp":"彼は頭がいい。それに、スポーツも得意だ。","en":"He is smart. In addition, he is good at sports.","romaji":"Kare wa atama ga ii. Soreni, supo-tsu mo tokui da."},{"jp":"このケーキはおいしい。それに、値段も安い。","en":"This cake is delicious. Besides, the price is also cheap.","romaji":"Kono keeki wa oishii. Soreni, nedan mo yasui."},{"jp":"私は日本語が話せます。それに、韓国語も話せます。","en":"I can speak Japanese. On top of that, I can also speak Korean.","romaji":"Watashi wa nihongo ga hanasemasu. Soreni, kankokugo mo hanasemasu."},{"jp":"彼女は美人だ。それに、性格もいい。","en":"She is beautiful. In addition, she has a good personality.","romaji":"Kanojo wa bijin da. Soreni, seikaku mo ii."}],"example":"彼は頭がいい。それに、スポーツも得意だ。","exampleMeaning":"He is smart. In addition, he is good at sports."},{"pattern":"文A。だから 文B (Bun A. Dakara Bun B)","meaning":"Express reason or cause; 'because', 'so', 'therefore'.","formation":"Sentence A + だから + Sentence B","examples":[{"jp":"明日は試験だ。だから今日勉強しなければならない。","en":"Tomorrow is the exam, so I have to study today.","romaji":"Ashita wa shiken da. Dakara kyou benkyou shinakereba naranai."},{"jp":"この料理は簡単だ。だから初心者でも作れる。","en":"This dish is simple, so even beginners can make it.","romaji":"Kono ryouri wa kantan da. Dakara shoshinsha demo tsukureru."},{"jp":"彼は病気だ。だから今日学校を休む。","en":"He is sick, so he will take a day off from school today.","romaji":"Kare wa byouki da. Dakara kyou gakkou wo yasumu."},{"jp":"駅まで遠い。だからタクシーで行ったほうがいい。","en":"The station is far, so it's better to go by taxi.","romaji":"Eki made tooi. Dakara takushii de itta hou ga ii."}],"example":"明日は試験だ。だから今日勉強しなければならない。","exampleMeaning":"Tomorrow is the exam, so I have to study today."}]
